// AAMC full-length tests: flashcards built from the concepts tested in each test's sections.
// One scenario card per tested concept, checked against AAMC's answers and explanations.
// Original wording only: no AAMC passages, questions, figures or explanations are reproduced.
// src = test and question number the concept came from (e.g. pe5-cp:28 = Practice Exam 5, Chem/Phys, Q28).
// Format: {s: tag, disc: scoring discipline, aamc: content category, q, choices: [4], ans: 0-3, exp, src}
const QB_AAMC_FL = [
  // ── Practice Exam 5 · Chem/Phys (built 2026-11-11) ──
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'To make 100.0 mL of a 60 μM solution of a drug (molar mass 484 g/mol), about how much drug do you need?',choices:['2.9 mg','29 mg','0.29 mg','5.8 mg'],ans:0,exp:'moles = M × L = 60 × 10⁻⁶ × 0.100 = 6 × 10⁻⁶ mol; × 484 g/mol ≈ 2.9 × 10⁻³ g = **2.9 mg**. Convert μM to M and mL to L first.',src:'pe5-cp:1'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'Adding more inhibitor increases the amount of enzyme–inhibitor complex. Which principle explains this?',choices:['Heisenberg\'s uncertainty principle','Le Châtelier\'s principle','The Pauli exclusion principle','Hund\'s rule'],ans:1,exp:'E + I ⇌ EI is an equilibrium. Raising [I] is a stress, so the system shifts to use it up, forming more EI: **Le Châtelier**. The other three are about electrons or quantum limits.',src:'pe5-cp:2'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'Which change would make a drug molecule MORE water-soluble?',choices:['Replacing an N–H with N–CH₃','Replacing a C=O with C=CH₂','Replacing a ring CH with a ring N','Replacing an O–H with O–CH₃'],ans:2,exp:'A ring N has a lone pair that can **accept a hydrogen bond** from water. The other changes remove H-bond donors or polarity, which lowers solubility.',src:'pe5-cp:3'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'An inhibitor\'s concentration is raised from 60 μM to 180 μM. What happens to its Ki?',choices:['It triples','It drops to one-third','It stays the same','It doubles'],ans:2,exp:'**Ki is an equilibrium (dissociation) constant**, a property of the inhibitor and enzyme. Changing [I] changes how much inhibition you see, not Ki itself.',src:'pe5-cp:4'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'An enzyme adds two electrons and two hydrogens to a ketone. What forms?',choices:['A carboxylic acid','An ester','An aldehyde','A secondary alcohol'],ans:3,exp:'Reducing a ketone, R–C(=O)–R, gives R–CH(OH)–R: a **secondary alcohol**. Losing electrons would go the other way (toward acids).',src:'pe5-cp:5'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'FAD and FMN share which redox-active component?',choices:['Flavin','Adenine','Ubiquinone','Imidazole'],ans:0,exp:'Both are **flavin** cofactors (the "F"). Adenine is only in FAD, ubiquinone is a separate electron carrier, and imidazole is histidine\'s side chain.',src:'pe5-cp:6'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'A solution has 150 mM Na⁺ and 0.75 mM enzyme. What is the cation-to-enzyme ratio?',choices:['2:1','200:1','20:1','1:2'],ans:1,exp:'Divide the concentrations in the same units: 150 ÷ 0.75 = **200**, so 200:1. Passage ratio questions often hide the two numbers in different sentences.',src:'pe5-cp:7'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'4C',q:'An exergonic redox reaction releases little heat inside a cell. What best explains this?',choices:['A catalyst makes it more exothermic','Splitting it into steps lowers its total ΔH','The reactants stay far apart from each other','Its energy pumps ions against a gradient'],ans:3,exp:'The energy is **coupled** to work: moving a charged particle against its gradient. Catalysts and extra steps don\'t change overall thermodynamics (Hess\'s law), and reactants must meet to react.',src:'pe5-cp:8'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4B',q:'Two open tanks hold different volumes of the same liquid. How do the pressures compare 10 cm below each surface?',choices:['Greater in the larger tank','Equal in both tanks','Greater in the smaller tank','Cannot be compared'],ans:1,exp:'P = P_atm + **ρgh**. Same liquid, same depth → same pressure. The amount of liquid or the tank\'s shape doesn\'t matter.',src:'pe5-cp:9'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4E',q:'An atom has 6 protons and 8 neutrons. What element is it?',choices:['Oxygen','Nitrogen','Carbon','Silicon'],ans:2,exp:'The **number of protons** (atomic number) decides the element: 6 = carbon. Neutrons only set the isotope (here carbon-14).',src:'pe5-cp:10'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'Which molecule is polar?',choices:['CCl₄','CO₂','BF₃','NF₃'],ans:3,exp:'NF₃ has a lone pair on N, making it **trigonal pyramidal**, so its bond dipoles don\'t cancel. CCl₄ (tetrahedral), CO₂ (linear) and BF₃ (trigonal planar) are symmetric, so their dipoles cancel.',src:'pe5-cp:11'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'All else held constant, which change would NOT double a gas\'s volume?',choices:['Doubling the pressure','Doubling the kelvin temperature','Halving the pressure','Doubling the moles of gas'],ans:0,exp:'V ∝ nT/P. Doubling **pressure** halves the volume (Boyle). Doubling T or n, or halving P, each doubles V.',src:'pe5-cp:12'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4E',q:'How many neutrons are in krypton-86 (atomic number 36)?',choices:['36','86','50','122'],ans:2,exp:'Neutrons = mass number − atomic number = 86 − 36 = **50**.',src:'pe5-cp:13'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Pyrrole is a five-membered aromatic ring containing one nitrogen. What is its formula?',choices:['C₄H₅N','C₅H₅N','C₄H₄N','C₆H₇N'],ans:0,exp:'Pyrrole = 4 ring carbons + 1 N, with an H on each atom: **C₄H₅N**. C₅H₅N is pyridine, the six-membered ring.',src:'pe5-cp:14'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'About how many moles of gas fill an 11 cm³ tube at 0 °C and 1 atm?',choices:['2 × 10⁻⁶','5 × 10⁻⁴','4 × 10⁻⁵','0.5'],ans:1,exp:'At STP, 1 mol of gas fills **22.4 L = 22,400 cm³**. 11 ÷ 22,400 ≈ **5 × 10⁻⁴ mol**.',src:'pe5-cp:15'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4D',q:'Why can 605 nm light NOT make a sample fluoresce at 450 nm?',choices:['Visible light is too weak to excite any molecule','605 nm photons carry more energy than 450 nm ones','An emitted photon can\'t carry more energy than the absorbed one','Longer wavelengths are absorbed by water first'],ans:2,exp:'Fluorescence emits a **lower-energy (longer-λ)** photon than the one absorbed. Since E = hc/λ, 605 nm photons have less energy than 450 nm ones, so they can\'t produce them.',src:'pe5-cp:16'},
  {s:'Practice Exam 5: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'Circular dichroism of a protein mainly detects the chirality of which atom?',choices:['The α carbon','The amide nitrogen','The carbonyl carbon','The β carbon'],ans:0,exp:'Every amino acid except glycine has a **chiral α carbon**. Amide N and carbonyl C are not chiral, and the β carbon is chiral only in Ile and Thr.',src:'pe5-cp:17'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'A mutation swaps leucine for serine. Which property of that side chain does NOT change?',choices:['Hydrophobicity','Mass','Hydrogen-bonding ability','Net charge'],ans:3,exp:'Leu (greasy) → Ser (polar OH): hydrophobicity, mass and H-bonding all change. **Neither is charged**, so the net charge stays the same.',src:'pe5-cp:18'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5C',q:'A protein is digested over time, and samples are run on SDS-PAGE. What pattern appears?',choices:['The full-size band fades; smaller bands appear','Bands shift up to larger sizes over time','Every band stays the same over time','New bands appear above the original'],ans:0,exp:'Proteolysis cuts the protein, so the **original band shrinks** while **lower-weight fragments** appear. Bands moving up would mean aggregation, not digestion.',src:'pe5-cp:19'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'A methyltransferase moves a CH₃ group from a cofactor to a substrate. What is the net mass change of substrate plus cofactor together?',choices:['+15 g/mol','0 g/mol','−15 g/mol','+30 g/mol'],ans:1,exp:'A **transferase only moves** atoms. The substrate gains 15 and the cofactor loses 15, so the combined change is **0**.',src:'pe5-cp:20'},
  {s:'Practice Exam 5: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'Progesterone and other steroid hormones are made from which molecule?',choices:['Glucose','Glycerol','Phenylalanine','Cholesterol'],ans:3,exp:'All **steroids come from cholesterol** (isoprene → squalene → cholesterol). Glucose is a sugar, glycerol is the fat backbone, and phenylalanine is an amino acid.',src:'pe5-cp:21'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5C',q:'A His-tagged protein sticks to a nickel column and is released with imidazole. What type of chromatography is this?',choices:['Size exclusion','Affinity','Cation exchange','Anion exchange'],ans:1,exp:'Binding through a **specific tag** (His₆ to Ni²⁺) and releasing it with a competitor is **affinity chromatography**. Size exclusion sorts by size; ion exchange sorts by charge.',src:'pe5-cp:22'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'A detergent is used to free proteins from a membrane. Which feature makes it work?',choices:['Several chiral centers in a fixed pattern','Many bonds that are easily hydrolyzed','Both large greasy and water-loving regions','A reducing sugar at one end'],ans:2,exp:'Detergents are **amphipathic**: a greasy part mixes with membrane lipids and a polar part faces water, pulling proteins into solution.',src:'pe5-cp:23'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'How many moles of NaCl are in 500 mL of 300 mM NaCl?',choices:['0.15 mol','0.015 mol','1.5 mol','0.6 mol'],ans:0,exp:'moles = M × L = 0.300 mol/L × 0.500 L = **0.15 mol**. Convert mM → M and mL → L.',src:'pe5-cp:24'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'What best shows that a purified protein is still in its native, folded state?',choices:['It kept its purification tags','It passed two chromatography steps','Its molecular weight matches the literature','Its binding activity matches the native protein'],ans:3,exp:'Only **function** proves native structure. Tags, purification steps and molecular weight can all be the same in a denatured protein.',src:'pe5-cp:25'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4E',q:'Why does nuclear fusion need extremely high temperatures?',choices:['To switch off the strong nuclear force','So nuclei can get close enough to fuse','To strip all charge from the nuclei','To lower the density of the fuel'],ans:1,exp:'Nuclei are positive and repel. High temperature gives them enough speed to overcome that repulsion and come within range of the **strong nuclear force**.',src:'pe5-cp:26'},
  {s:'Practice Exam 5: Chem/Phys',disc:'organic_chem',aamc:'5B',q:'Two enantiomers can differ in which property?',choices:['Boiling point','Density','How they smell','IR spectrum'],ans:2,exp:'Enantiomers have identical physical properties **except** in chiral environments: they rotate light opposite ways and can interact differently with chiral receptors, like smell receptors.',src:'pe5-cp:27'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4B',q:'Blood flows at 30 cm/s in a tube 1.6 cm wide. How fast does it flow where the tube narrows to 0.8 cm wide?',choices:['60 cm/s','15 cm/s','7.5 cm/s','120 cm/s'],ans:3,exp:'Continuity: A₁v₁ = A₂v₂. Area ∝ diameter², so halving the diameter makes the area **¼**, and the speed **4×**: 120 cm/s.',src:'pe5-cp:28'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Which ion has a noble-gas electron configuration?',choices:['Ca²⁺','Cu²⁺','Fe²⁺','Zn⁺'],ans:0,exp:'Ca²⁺ loses its two 4s electrons, leaving the **argon** configuration. Transition-metal ions like Cu²⁺, Fe²⁺ and Zn⁺ keep d electrons.',src:'pe5-cp:29'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'A tryptophan side chain gains a –COOH group. How is it now classified at pH 7?',choices:['Basic','Acidic','Hydrophobic','Polar neutral'],ans:1,exp:'A COOH loses its proton at pH 7 (→ COO⁻), so the residue now behaves as **acidic** and negatively charged.',src:'pe5-cp:31'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Which amino acid side chain contains an imidazole ring?',choices:['Tryptophan','Proline','Histidine','Tyrosine'],ans:2,exp:'**Histidine = imidazole.** Tryptophan has an indole, proline a ring through the backbone N, and tyrosine a phenol.',src:'pe5-cp:32'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Heating a protein to 75 °C makes a buried residue react with a chemical. Why?',choices:['Its peptide bonds break','Its disulfide bonds are reduced','The solvent dissolves the protein\'s core','The protein unfolds and exposes it'],ans:3,exp:'Heat **denatures** the protein: it unfolds (primary structure unchanged), so buried residues become reachable.',src:'pe5-cp:33'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'Which formula is ammonium acetate?',choices:['NH₄CH₃CO₂','NH₄HCO₃','(NH₄)₂CO₃','NH₄HCO₂'],ans:0,exp:'Acetate = CH₃CO₂⁻, so ammonium acetate is **NH₄CH₃CO₂**. NH₄HCO₃ is bicarbonate, (NH₄)₂CO₃ is carbonate, and NH₄HCO₂ is formate.',src:'pe5-cp:34'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5C',q:'Two forms of a protein are both negatively charged, but one is more negative. Which technique separates them?',choices:['Cation-exchange chromatography','Anion-exchange chromatography','Gas chromatography','Size-exclusion chromatography'],ans:1,exp:'**Anion exchange** has a positive column that holds negative proteins; the more negative form binds tighter and elutes later. Cation exchange wouldn\'t hold either one.',src:'pe5-cp:35'},
  {s:'Practice Exam 5: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'A C=O sits inside a ring, with ring carbons on both sides of it. What functional group is it?',choices:['Ester','Carboxylic acid','Aldehyde','Ketone'],ans:3,exp:'C=O with **carbons on both sides = ketone**. Aldehydes have an H on the C=O; acids and esters have an O on it.',src:'pe5-cp:36'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'In a sealed flask at constant temperature, 4 mol of gas react to form 2 mol of gas. If the starting pressure is 1.0 atm, what is the final pressure?',choices:['0.50 atm','0.25 atm','1.0 atm','2.0 atm'],ans:0,exp:'At constant V and T, **P ∝ moles of gas**. Half the moles → half the pressure: 0.50 atm. Count only gases.',src:'pe5-cp:37'},
  {s:'Practice Exam 5: Chem/Phys',disc:'organic_chem',aamc:'5C',q:'A lipophilic compound is shaken with water and an ether. Where does it end up?',choices:['In the water layer','In the ether layer','Split evenly between the layers','As a solid between the layers'],ans:1,exp:'**Like dissolves like**: a lipophilic (greasy) compound moves into the nonpolar organic layer.',src:'pe5-cp:38'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'On a semi-log plot of enzyme activity against inhibitor concentration, where do you read Ki?',choices:['Where activity first starts to drop','Where activity reaches zero','At half of maximum activity, the midpoint','At the highest concentration tested'],ans:2,exp:'Ki is the inhibitor concentration that gives **half** the maximum activity: the midpoint (inflection) of the S-shaped curve.',src:'pe5-cp:39'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'A Hill coefficient of 2.5 means binding is:',choices:['negatively cooperative','not cooperative','positively cooperative','irreversible'],ans:2,exp:'Hill n **> 1 = positive cooperativity** (one binding makes the next easier); n = 1 none; n < 1 negative. Hemoglobin is the classic example.',src:'pe5-cp:40'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'A pathway makes a flavor compound, then converts it into an irritant. To keep the flavor but stop the irritant, which step should be blocked?',choices:['The first step of the pathway','The step that makes the flavor','The last step, after the flavor forms','Every step equally'],ans:2,exp:'Block **downstream** of what you want to keep. Blocking earlier steps would stop the flavor too.',src:'pe5-cp:41'},
  {s:'Practice Exam 5: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'A negatively charged phosphate is held by a salt bridge, and its aromatic ring by π-stacking. Which pair of residues fits?',choices:['Asp and Tyr','Glu and Ser','Lys and Ser','Arg and Tyr'],ans:3,exp:'Salt bridge to a **negative** phosphate needs a **positive** side chain (Arg or Lys). π-stacking needs an **aromatic** ring (Tyr, Phe, Trp). Only Arg + Tyr does both.',src:'pe5-cp:42'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'A reaction is described as both fast and spontaneous. Which pair fits?',choices:['High Ea, ΔG > 0','High Ea, ΔG < 0','Low Ea, ΔG > 0','Low Ea, ΔG < 0'],ans:3,exp:'**Fast = low Ea** (kinetics). **Spontaneous = ΔG < 0** (thermodynamics). They are separate questions: a spontaneous reaction can still be slow.',src:'pe5-cp:44'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'As pH rises, which group on a chlorinated amino acid loses its proton first?',choices:['The COOH next to two Cl atoms','The protonated amine','A side-chain alcohol OH','A COOH far from the Cl atoms'],ans:0,exp:'The **most acidic** group (lowest pKa) loses H⁺ first. COOH (pKa ~2–5) beats NH₃⁺ (~9–10) and OH. Nearby electron-withdrawing Cl stabilizes the anion, so that COOH is the most acidic.',src:'pe5-cp:45'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'On an energy diagram, reactants sit at E2, products lower at E1, and the peak at E3. What is the forward activation energy?',choices:['E2 − E1','E3 − E1','E3 − E2','E1 − E3'],ans:2,exp:'Ea = **peak − reactants** = E3 − E2. E2 − E1 is the energy released (ΔH), and E3 − E1 is the reverse activation energy.',src:'pe5-cp:46'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4A',q:'A 2 kg mass and a 5 kg mass hang on either side of a frictionless pulley. What is their acceleration once released?',choices:['g','3g/7','2g/7','5g/7'],ans:1,exp:'a = (m₁ − m₂)g / (m₁ + m₂) = (5 − 2)g / 7 = **3g/7**. The net pull is the weight difference; the total mass being accelerated is the sum.',src:'pe5-cp:47'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'Turning ice at 0 °C into steam at 100 °C, which step takes the most heat?',choices:['Melting the ice','Warming the water from 0 to 50 °C','Warming the water from 50 to 100 °C','Boiling the water into steam'],ans:3,exp:'Per gram: melting 80 cal, each 50 °C of warming 50 cal, **vaporizing 540 cal**. Phase changes, especially boiling, take the most heat.',src:'pe5-cp:48'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4B',q:'A 100 N force pushes straight on a 10 cm × 5 cm paddle. What pressure does it apply?',choices:['5 kPa','10 kPa','20 kPa','2 kPa'],ans:2,exp:'P = F/A. Area = 0.10 m × 0.05 m = 0.005 m². 100 ÷ 0.005 = **20,000 Pa = 20 kPa**. Convert cm to m first.',src:'pe5-cp:49'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4C',q:'A 25 μF capacitor charged to 3000 V discharges completely in 10 ms. What is the average current?',choices:['7.5 A','75 A','0.75 A','30 A'],ans:0,exp:'Q = CV = 25 × 10⁻⁶ × 3000 = 0.075 C. I = Q/t = 0.075 ÷ 0.010 = **7.5 A**.',src:'pe5-cp:50'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4C',q:'With the voltage fixed, which change increases the charge a parallel-plate capacitor stores?',choices:['Shrinking the plate area','Moving the plates closer together','Removing the dielectric','Lowering the voltage'],ans:1,exp:'C = κε₀A/d and Q = CV. A **smaller gap (d)** raises C, so more charge at the same V. Less area, no dielectric or lower V all reduce Q.',src:'pe5-cp:51'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4C',q:'A 25 μF capacitor at 3000 V is replaced with a 30 μF capacitor. What voltage stores the same charge?',choices:['3600 V','3000 V','3500 V','2500 V'],ans:3,exp:'Same Q = CV. Q = 25 μF × 3000 V = 75 mC; V = 75 mC ÷ 30 μF = **2500 V**. Bigger C needs less V for the same charge.',src:'pe5-cp:52'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4D',q:'If a light wave\'s wavelength doubles, its frequency:',choices:['halves','doubles','drops to a quarter','stays the same'],ans:0,exp:'c = fλ is fixed, so f and λ are **inversely** related: double λ → half f.',src:'pe5-cp:53'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4D',q:'If a photon\'s energy doubles, which property also doubles?',choices:['Its wavelength','Its frequency','Its amplitude','Its intensity'],ans:1,exp:'**E = hf**, so E and f rise together. Wavelength halves (E = hc/λ). Single photons don\'t have an amplitude or intensity in this sense.',src:'pe5-cp:54'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4D',q:'Light of wavelength 600 nm has about what frequency?',choices:['5 × 10¹⁴ Hz','5 × 10⁻¹⁴ Hz','2 × 10¹⁵ Hz','2 × 10⁻¹⁵ Hz'],ans:0,exp:'f = c/λ = 3 × 10⁸ ÷ 6 × 10⁻⁷ = **5 × 10¹⁴ Hz**. Visible light is always about 10¹⁴–10¹⁵ Hz; a negative exponent is impossible.',src:'pe5-cp:55'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4D',q:'Using hc ≈ 1240 eV·nm, what is the wavelength of a 2 eV photon?',choices:['310 nm','740 nm','620 nm','450 nm'],ans:2,exp:'λ = hc/E = 1240 ÷ 2 = **620 nm** (orange-red light). Memorize **hc ≈ 1240 eV·nm** for fast photon math.',src:'pe5-cp:56'},
  {s:'Practice Exam 5: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'A weak acid has pKa = 5. What is Kb for its conjugate base?',choices:['10⁻⁵','10⁻⁹','10⁻²·⁵','10⁻¹⁹'],ans:1,exp:'**pKa + pKb = 14**, so pKb = 9 and Kb = **10⁻⁹**. The weaker the acid, the stronger its conjugate base.',src:'pe5-cp:57'},
  {s:'Practice Exam 5: Chem/Phys',disc:'organic_chem',aamc:'5E',q:'Which change will NOT raise the final yield of an ester made at equilibrium?',choices:['Adding twice as much enzyme','Adding more of the alcohol','Adding more of the carboxylic acid','Removing the ester as it forms'],ans:0,exp:'An enzyme (catalyst) speeds the reaction but **doesn\'t shift equilibrium**. Adding reactants or removing product shifts it toward ester (Le Châtelier).',src:'pe5-cp:58'},
  {s:'Practice Exam 5: Chem/Phys',disc:'physics',aamc:'4A',q:'A pushing force drops steadily from 100 N to 0 N over 20 m. How much work is done?',choices:['500 J','2000 J','4000 J','1000 J'],ans:3,exp:'Work = **area under the force–distance graph**. A triangle: ½ × 100 N × 20 m = **1000 J**.',src:'pe5-cp:59'},
  // ── Practice Exam 1 · Chem/Phys (built 2026-11-11) ──
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'5C',q:'In paper chromatography, water held on the paper is the stationary phase. What mainly controls how far each compound travels?',choices:['Hydrogen bonding with that water','How much sample was spotted','How thick the paper is','How much water the paper holds'],ans:0,exp:'Compounds that **hydrogen bond** strongly with the stationary water stick and move **slowly**; weak H-bonders travel farther. Spot size changes the spot, not how far it moves.',src:'pe1-cp:1'},
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'5C',q:'On a TLC plate, a spot moves 2 cm while the solvent front moves 10 cm. What is its Rf?',choices:['5','0.20','2','10'],ans:1,exp:'**Rf = spot distance ÷ solvent-front distance** = 2 ÷ 10 = 0.20. Rf is always between 0 and 1, so 5 and 10 are impossible.',src:'pe1-cp:3'},
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'5C',q:'Acid-catalyzed dehydration of an alcohol goes through a carbocation. Which statement about it is FALSE?',choices:['Tertiary alcohols react most easily','A water molecule is lost','A carbocation forms','It gives only one alkene stereoisomer'],ans:3,exp:'The flat **carbocation** can lose an H⁺ from either side, giving a **mix of cis and trans** alkenes, so the reaction is not stereospecific. Tertiary alcohols form the most stable carbocations, so they react fastest.',src:'pe1-cp:4'},
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'When two amino acids join through a peptide bond, which functional group forms?',choices:['An amine','An aldehyde','An amide','A carboxyl'],ans:2,exp:'The COOH of one amino acid and the NH₂ of the next combine (losing water) into **–C(=O)–NH–**, an **amide**. Amine and carboxyl are the starting groups.',src:'pe1-cp:5'},
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'By an SN2 path, a primary alcohol becomes an alkyl halide faster than a secondary alcohol does. Why?',choices:['The secondary C–O bond is stronger','Elimination competes and slows it','Its OH is harder to protonate','More crowding at the secondary carbon'],ans:3,exp:'SN2 needs a **backside attack**. More groups on the carbon (secondary vs primary) block the nucleophile: **steric hindrance**. Rate: methyl > 1° > 2°; tertiary doesn\'t do SN2.',src:'pe1-cp:6'},
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'An alcohol forms a tertiary carbocation in HCl. Which product could form ONLY after a rearrangement?',choices:['The alkene from losing a neighboring H⁺','Chloride bonded to the carbocation carbon','Chloride bonded to a different carbon','The original alcohol re-formed'],ans:2,exp:'Direct products form at the **carbocation carbon** (Cl⁻ adds there) or by losing a neighboring H⁺ (alkene). A group on a **different carbon** means the positive charge moved first (a 1,2-hydride or methyl shift).',src:'pe1-cp:7'},
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'5C',q:'An alcohol, an alkene, an alkyl chloride and an alkyl bromide of similar size are injected into a gas chromatograph. Which comes out first?',choices:['The alcohol','The alkyl chloride','The alkyl bromide','The alkene'],ans:3,exp:'In GC, the **most volatile** (lowest boiling) compound exits first. The nonpolar alkene has only London forces; the alcohol hydrogen bonds and comes out last.',src:'pe1-cp:8'},
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'5B',q:'An (R) stereocenter undergoes SN2 substitution, and the new group takes the leaving group\'s priority. What configuration results?',choices:['(R), with retention','(S), with inversion','A racemic mixture','No stereocenter remains'],ans:1,exp:'SN2 = **backside attack = inversion** (like an umbrella flipping). With the same priority order, R becomes **S**. SN1, through a flat carbocation, would give a racemic mix.',src:'pe1-cp:9'},
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'To find out which reactant loses its –OH when a carboxylic acid and an alcohol form an ester, which label works best?',choices:['D on the acid\'s O–H','D on the alcohol\'s O–H','¹⁸O in the acid\'s C=O','¹⁸O in the alcohol\'s O'],ans:3,exp:'Label the **alcohol\'s oxygen**. If the ¹⁸O ends up in the ester, the alcohol kept its O and the **acid lost its OH** (as water). H/D labels scramble by exchange, so they tell you nothing.',src:'pe1-cp:10'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4D',q:'An eye\'s lens sits 2.0 cm from the retina and focuses an object 1.0 m away. About what is the lens strength? (1/f = 1/o + 1/i)',choices:['51 D','−50 D','−10 D','55 D'],ans:0,exp:'Power (diopters) = 1/f in **meters** = 1/1.0 + 1/0.020 = 1 + 50 = **51 D**. The eye\'s lens converges, so it must be positive.',src:'pe1-cp:11'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'How does an enzyme speed up a reaction?',choices:['It stabilizes the substrate, changing ΔG','It stabilizes the transition state, changing ΔG','It stabilizes the substrate, lowering Ea','It stabilizes the transition state, lowering Ea'],ans:3,exp:'Enzymes bind and **stabilize the transition state**, which **lowers Ea**. They never change ΔG or the equilibrium. Stabilizing the substrate would actually raise Ea.',src:'pe1-cp:12'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'Which change LOWERS the percent ionization of 1.0 M acetic acid?',choices:['Adding a chlorine to its CH₃ group','Diluting it with water','Adding concentrated HCl','Adding a drop of base'],ans:2,exp:'HCl adds lots of **H⁺, a common ion**, pushing CH₃COOH ⇌ H⁺ + CH₃COO⁻ back to the left. Dilution, removing H⁺ with base, or adding an electron-withdrawing Cl all increase ionization.',src:'pe1-cp:13'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4C',q:'The current in a circuit rises while its resistance stays the same. What happens to the voltage?',choices:['It falls','It rises','It stays the same','It drops to zero'],ans:1,exp:'**V = IR.** With R fixed, V and I rise together.',src:'pe1-cp:14'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4D',q:'Light travels at 2.1 × 10⁸ m/s in a fluid. What is the fluid\'s index of refraction?',choices:['0.7','1.4','2.1','3.0'],ans:1,exp:'**n = c/v** = 3.0 × 10⁸ ÷ 2.1 × 10⁸ ≈ 1.4. n is always ≥ 1, since nothing is faster than light in vacuum.',src:'pe1-cp:15'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4D',q:'For light of a single color, intensity is directly proportional to the:',choices:['speed the light travels at','wavelength of the light','polarization of the light','photon count per second'],ans:3,exp:'For one color (fixed photon energy), brighter light means **more photons per second**. Speed and wavelength don\'t set brightness.',src:'pe1-cp:16'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4D',q:'What is the energy of a photon at 610 THz? (h = 6.6 × 10⁻³⁴ J·s)',choices:['4.0 × 10⁻¹⁹ J','1.1 × 10⁻¹⁸ J','9.2 × 10⁻¹² J','1.6 × 10⁻¹⁶ J'],ans:0,exp:'E = hf. **1 THz = 10¹² Hz**, so 6.6 × 10⁻³⁴ × 6.1 × 10¹⁴ ≈ **4.0 × 10⁻¹⁹ J**. Visible photons are always around 10⁻¹⁹ J.',src:'pe1-cp:17'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'Pulse pressure is 120 − 75 = 45 mmHg. About what percent of atmospheric pressure (760 mmHg) is that?',choices:['10%','2%','6%','1%'],ans:2,exp:'45 ÷ 760 ≈ 0.06 = **6%**. Remember 1 atm = 760 mmHg.',src:'pe1-cp:19'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4E',q:'An isotope has a 2-minute half-life. What fraction of a sample has decayed after 10 minutes?',choices:['1/32','31/32','15/16','1/2'],ans:1,exp:'10 min = **5 half-lives**, so (½)⁵ = 1/32 **remains** and 31/32 has **decayed**. Read whether the question asks about what remains or what decayed.',src:'pe1-cp:20'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4A',q:'A heart pumps with an average power of 200 W for 10 minutes. How much work does it do?',choices:['2 kJ','120 kJ','20 kJ','12 kJ'],ans:1,exp:'Work = power × time = 200 W × **600 s** = 120,000 J = **120 kJ**. Convert minutes to seconds first.',src:'pe1-cp:21'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Peptide fibers are cross-linked by disulfide bridges between cysteines. What kind of interaction is that?',choices:['Intermolecular hydrogen bonding','Intramolecular hydrogen bonding','Intermolecular covalent bonding','Ionic bonding between chains'],ans:2,exp:'A **disulfide (S–S) bond is covalent**, and linking two different chains makes it **inter**molecular. It makes the structure much more rigid than hydrogen bonds alone.',src:'pe1-cp:22'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Many cell-adhesion peptides contain the RGD motif. Which of its residues can form strong ionic attractions?',choices:['Arg and Asp','Gly and Asp','Arg and Gly','Cys and Gly'],ans:0,exp:'**R (Arg) is positive and D (Asp) is negative**, so both can make electrostatic contacts. Glycine has only an H for a side chain.',src:'pe1-cp:23'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Which amino acid has a primary alcohol (–CH₂OH) side chain?',choices:['Threonine','Tyrosine','Alanine','Serine'],ans:3,exp:'**Serine = CH₂OH (primary)**. Threonine\'s OH is on a secondary carbon, tyrosine\'s is a phenol, and alanine has just CH₃. Ser, Thr and Tyr are the classic phosphorylation sites.',src:'pe1-cp:24'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'A peptide self-assembles at low pH but not at high pH. Which feature explains this?',choices:['Side chains whose charge changes with pH','A long greasy alkyl tail','Thiol groups that hydrogen bond','Bonds that hydrolyze reversibly'],ans:0,exp:'pH only matters through groups that **gain or lose H⁺**. At low pH, acidic side chains are neutral, so charge repulsion drops and the peptides stick together. A greasy tail doesn\'t respond to pH.',src:'pe1-cp:25'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biology',aamc:'4B',q:'Why does blood flow slowest in the capillaries?',choices:['Capillary walls are more elastic','Capillaries resist flow less','Their total cross-sectional area is largest','Pressure is higher in capillaries'],ans:2,exp:'Continuity: flow = area × speed. Billions of capillaries together have the **largest total area**, so blood moves **slowest** there, which leaves time for exchange.',src:'pe1-cp:26'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'Which hybridization gives an octahedral central atom?',choices:['sp³','d²sp³','sp²','sp'],ans:1,exp:'Six electron domains need **six hybrid orbitals**: d²sp³ (or sp³d²). sp = 2 (linear), sp² = 3 (trigonal), sp³ = 4 (tetrahedral).',src:'pe1-cp:28'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'Which is an assumption of the ideal gas model?',choices:['Molecules attract each other strongly','No molecular volume and no attractions','One mole fills 22.4 L at 25 °C','Molecules take up most of the volume'],ans:1,exp:'Ideal gases have **negligible molecular volume and no intermolecular forces**. 22.4 L is at **0 °C** (STP), not 25 °C.',src:'pe1-cp:29'},
  {s:'Practice Exam 1: Chem/Phys',disc:'organic_chem',aamc:'4D',q:'Cone cells contain several opsins that absorb at different wavelengths. What does that allow?',choices:['Better night vision','Faster pigment recovery','Seeing different colors','Changing the lens\'s focus'],ans:2,exp:'Different opsins absorb **different wavelengths**, which is the basis of **color vision**. Rods handle dim light.',src:'pe1-cp:30'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'A binding pocket holds retinal, a molecule made almost entirely of C–H bonds. What is the pocket most likely like?',choices:['Hydrophilic','Positively charged','Negatively charged','Hydrophobic'],ans:3,exp:'**Like binds like.** A nonpolar guest needs a **nonpolar (hydrophobic)** pocket. Charged pockets bind charged guests.',src:'pe1-cp:31'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'A kinase phosphorylates a protein. Where does the phosphate come from?',choices:['ATP','The kinase itself','The protein\'s binding partner','A water molecule'],ans:0,exp:'Kinases **transfer the γ-phosphate of ATP** to their target. The kinase is only the catalyst.',src:'pe1-cp:32'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'How are the carbons of a C=C double bond hybridized? (Each has three groups and no lone pairs.)',choices:['sp','sp³','sp²','sp³d'],ans:2,exp:'Three electron domains → **sp²**, trigonal planar. The leftover p orbital forms the π bond, which is why C=C can\'t rotate freely (cis/trans).',src:'pe1-cp:33'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'What reaction does a lipase catalyze?',choices:['ATP hydrolysis','Peptide bond cleavage','Transfer of a carboxyl group','Hydrolysis of triacylglycerols'],ans:3,exp:'**Lipases hydrolyze fats (triacylglycerols)** at their ester bonds. Proteases cut peptide bonds; transferases move groups.',src:'pe1-cp:34'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'At pH 7, a protein has three mutations: Arg → Gly, Lys → Asp and Met → Asp. What is the change in net charge?',choices:['+4','−4','−3','+3'],ans:1,exp:'Arg (+1) → Gly (0): −1. Lys (+1) → Asp (−1): −2. Met (0) → Asp (−1): −1. Total **−4**. Count each mutation separately, then add.',src:'pe1-cp:35'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'Solution B has a pH 3 units lower than solution A. By what factor is [H⁺] higher in B?',choices:['3','30','1000','300'],ans:2,exp:'pH is a **log scale**: each unit is 10×. Three units = 10³ = **1000×**.',src:'pe1-cp:37'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Glycogen synthase links glucose units into chains with which bond?',choices:['α-1,4-glycosidic','α-1,6-glycosidic','β-1,4-glycosidic','β-1,6-glycosidic'],ans:0,exp:'Glycogen chains are **α-1,4**; the branching enzyme adds **α-1,6** branches. β-1,4 links make cellulose.',src:'pe1-cp:39'},
  {s:'Practice Exam 1: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'The nucleotide part of UDP-glucose contains which sugar?',choices:['Deoxyribose','Fructose','Ribose','Xylose'],ans:2,exp:'UDP is a **ribo**nucleotide (uridine = uracil + **ribose**). Deoxyribose is only in DNA nucleotides.',src:'pe1-cp:40'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4E',q:'Carbon-14 and phosphorus-32 both undergo β⁻ decay. Which atoms form?',choices:['Boron and silicon','Nitrogen and sulfur','Boron and sulfur','Nitrogen and silicon'],ans:1,exp:'**β⁻ decay: a neutron → proton + electron**, so the atomic number goes **up by 1**. C (6) → N (7); P (15) → S (16).',src:'pe1-cp:42'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'Which acid dissociates LEAST in water?',choices:['HCl','H₂SO₄','H₃PO₄','HPO₄²⁻'],ans:3,exp:'Pulling H⁺ off something that\'s **already negative** is hard. HPO₄²⁻ (2−) holds its proton most tightly. HCl and H₂SO₄ are strong acids.',src:'pe1-cp:44'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4D',q:'An object sits 3 focal lengths from a converging lens. What is the image height ÷ object height?',choices:['3/2','1/3','2/3','1/2'],ans:3,exp:'1/i = 1/f − 1/(3f) = 2/(3f), so i = 1.5f. **Magnification = i/o** = 1.5f ÷ 3f = **1/2**.',src:'pe1-cp:45'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4E',q:'In gamma decay, a nucleus emits:',choices:['a photon','a positron','a neutron','an electron'],ans:0,exp:'**Gamma = a high-energy photon**: no change in protons or neutrons. β⁺ emits a positron; β⁻ emits an electron.',src:'pe1-cp:46'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'A solid reacts with an acid to produce a gas, spontaneously at 25 °C. What are the signs of ΔG° and ΔS°?',choices:['ΔG° < 0 and ΔS° < 0','ΔG° < 0 and ΔS° > 0','ΔG° > 0 and ΔS° > 0','ΔG° > 0 and ΔS° < 0'],ans:1,exp:'**Spontaneous → ΔG < 0. Making a gas from a solid or liquid → ΔS > 0** (more disorder).',src:'pe1-cp:47'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'A two-step mechanism: H₂O₂ + I⁻ → H₂O + IO⁻, then H₂O₂ + IO⁻ → H₂O + O₂ + I⁻. What is the overall reaction?',choices:['2H₂O₂ → 2H₂O + O₂','H₂O₂ → H₂O + O₂','2H₂O₂ + I⁻ → 2H₂O + O₂ + I⁻','2H₂O₂ + IO⁻ → 2H₂O + I⁻ + O₂'],ans:0,exp:'Add the steps and **cancel** anything on both sides: IO⁻ (intermediate) and I⁻ (catalyst) cancel. Then check it\'s balanced; H₂O₂ → H₂O + O₂ isn\'t.',src:'pe1-cp:48'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'A homogeneous catalyst can\'t be separated from the products after a reaction. What is the result?',choices:['The catalyst becomes heterogeneous','The products end up contaminated','The reaction does not occur','The reaction speeds up'],ans:1,exp:'A homogeneous catalyst is in the **same phase** (often dissolved), so if you can\'t remove it, it stays mixed in with the product.',src:'pe1-cp:50'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'A solid catalyst is ground into a fine powder (same mass). What happens to the reaction rate?',choices:['It slows, as particles get in the way','It stays the same, as the mass is unchanged','It speeds up, as more surface is exposed','It stops, as the catalyst dissolves'],ans:2,exp:'Heterogeneous catalysts work at their **surface**. Grinding gives more surface area, so more reaction sites and a **faster** rate.',src:'pe1-cp:51'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4C',q:'Which change increases the current in a simple battery-and-bulb circuit?',choices:['Using thinner wire','Heating the wire','Using a lower-resistance bulb','Diluting the electrolyte solutions'],ans:2,exp:'**I = V/R**: lower R → more current. Thinner or hotter wire raises R, and diluting the cell\'s ions lowers its voltage.',src:'pe1-cp:52'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'4C',q:'A metal is more easily oxidized than zinc. Will it release H₂ from 0.1 M HCl?',choices:['Yes; the metal is reduced and H⁺ oxidized','Yes; the metal is oxidized and H⁺ reduced','No; the metal is reduced and Cl⁻ oxidized','No; the metal is oxidized and water forms'],ans:1,exp:'Active metals (like Zn and Al) give electrons to H⁺: **metal oxidized, H⁺ reduced to H₂**. Metals form cations, so they\'re never "reduced" here.',src:'pe1-cp:53'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Aluminum metal is placed in a Cu²⁺ solution. Which balanced reaction occurs?',choices:['2Al³⁺ + 3Cu → 2Al + 3Cu²⁺','2Al + 3Cu²⁺ → 2Al³⁺ + 3Cu','3Al + 2Cu²⁺ → 3Al³⁺ + 2Cu','3Al³⁺ + 2Cu → 3Al + 2Cu²⁺'],ans:1,exp:'Al (more active) is oxidized and Cu²⁺ is reduced. Balance charge: 3 Cu²⁺ (+6) = 2 Al³⁺ (+6). **Check the charge on both sides** to rule out the others.',src:'pe1-cp:54'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'4C',q:'Pb²⁺/Pb has E° = −0.127 V and Cu²⁺/Cu has E° = +0.339 V. In a cell where Cu²⁺ is reduced, what is E°cell, and is it spontaneous?',choices:['+0.212 V, not spontaneous','−0.466 V, spontaneous','+0.466 V, spontaneous','−0.212 V, not spontaneous'],ans:2,exp:'**E°cell = E°cathode − E°anode** = 0.339 − (−0.127) = +0.466 V. **Positive E°cell = spontaneous** (ΔG = −nFE).',src:'pe1-cp:55'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4C',q:'A 2.0 V source drives current through a 0.5 Ω bulb. What current flows?',choices:['1.0 A','4.0 A','0.25 A','2.0 A'],ans:1,exp:'**I = V/R** = 2.0 ÷ 0.5 = 4.0 A. Dividing by a number less than 1 makes the answer bigger.',src:'pe1-cp:56'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'Na₂CrO₄ is dissolved in a saturated BaCrO₄ solution. What happens?',choices:['More BaCrO₄ dissolves','Nothing changes','More BaCrO₄ precipitates','It dissolves, then precipitates'],ans:2,exp:'CrO₄²⁻ is a **common ion**: it pushes BaCrO₄ ⇌ Ba²⁺ + CrO₄²⁻ to the **left**, so solid forms.',src:'pe1-cp:57'},
  {s:'Practice Exam 1: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'What volume of a 0.120 M solution contains 0.078 mol of solute?',choices:['650 mL','65 mL','350 mL','35 mL'],ans:0,exp:'**V = moles ÷ M** = 0.078 ÷ 0.120 = 0.65 L = **650 mL**.',src:'pe1-cp:58'},
  {s:'Practice Exam 1: Chem/Phys',disc:'physics',aamc:'4A',q:'Which unit can NOT express power?',choices:['W','J·s⁻¹','kg·m²·s⁻²','ft·lb·s⁻¹'],ans:2,exp:'Power = energy per time. **kg·m²·s⁻² is a joule** (energy), with no "per second". Power in base units is kg·m²·s⁻³.',src:'pe1-cp:59'},
  // ── Practice Exam 3 · Chem/Phys (built 2026-11-11) ──
  {s:'Practice Exam 3: Chem/Phys',disc:'organic_chem',aamc:'5B',q:'A reaction is run under thermodynamic control, and isomer X makes up 80% of the mixture while isomer Y makes up 20%. What can you conclude?',choices:['X and Y are equally stable','X is more stable than Y','X is less stable than Y','Nothing about their stability'],ans:1,exp:'Under **thermodynamic control** the system reaches equilibrium, so the **major product is the more stable** one. (Kinetic control would instead favor the one that forms fastest.)',src:'pe3-cp:2'},
  {s:'Practice Exam 3: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'A ketone enolate attacks a second ketone (an aldol addition), and NO dehydration follows. What kind of product forms?',choices:['An α,β-unsaturated ketone','A β-hydroxy ketone','An ester','A carboxylic acid'],ans:1,exp:'Aldol **addition** makes a new C–C bond and turns the attacked C=O into an OH on the **β-carbon**: a **β-hydroxy ketone**. Only if water is then lost (condensation) do you get the α,β-unsaturated C=C.',src:'pe3-cp:3'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4C',q:'A 100 mF capacitor is connected to a 12 V battery. How much charge and energy does it store?',choices:['0.12 C and 14.4 J','1.2 C and 7.2 J','1.44 C and 0.12 J','7.2 C and 1.2 J'],ans:1,exp:'**Q = CV** = 0.100 F × 12 V = 1.2 C. **U = ½CV²** = ½ × 0.100 × 144 = 7.2 J. Watch the prefix: m = 10⁻³.',src:'pe3-cp:5'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4D',q:'You ride past a horn that emits frequency f. What pitch do you hear before and after you pass it?',choices:['Higher before, lower after','Lower before, higher after','Equal to f both times','Higher before and after'],ans:0,exp:'**Doppler effect:** moving **toward** a source → higher frequency; moving **away** → lower. It flips the moment you pass.',src:'pe3-cp:6'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4A',q:'A 1000 N friction force acts on a car moving at a steady 40 m/s. What power keeps it moving?',choices:['16 kW','40 kW','600 kW','800 kW'],ans:1,exp:'At constant speed, the engine must cancel friction. **P = F × v** = 1000 N × 40 m/s = 40,000 W = **40 kW**.',src:'pe3-cp:7'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4A',q:'A braking force is directly proportional to an object\'s speed. How does its speed change over time?',choices:['It drops linearly to zero','It stays constant','It drops quickly at first, then levels off','It drops slowly at first, then quickly'],ans:2,exp:'Force ∝ speed, so the deceleration is **big when fast and small when slow**. The speed curve starts steep and flattens out (exponential decay), never a straight line.',src:'pe3-cp:8'},
  {s:'Practice Exam 3: Chem/Phys',disc:'organic_chem',aamc:'5B',q:'Which measurement best compares the thermodynamic stability of two isomers?',choices:['Their boiling points','Their UV–visible spectra','Their mass-spec fragments','Their heats of combustion'],ans:3,exp:'Isomers burn to the **same products**, so any difference in heat released comes from their starting energy. **More stable isomer → lower heat of combustion.**',src:'pe3-cp:9'},
  {s:'Practice Exam 3: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'A tritium (³H) label must stay put in water. Which kind of position should carry it?',choices:['A carbon (C–H) position','An N–H position','An O–H position','Any position is fine'],ans:0,exp:'H on **O or N swaps with water** quickly, so the label would wash out. **C–H is not acidic enough** to exchange, so the label stays.',src:'pe3-cp:10'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'Which expression gives the number of gas PARTICLES (not moles) in volume V?',choices:['PV/RT','PV·N_A/RT','RT/PV','PV/(RT·N_A)'],ans:1,exp:'**n = PV/RT** gives moles. Multiply by **Avogadro\'s number (N_A)** to get particles. Remember T must be in kelvin (37 °C = 310 K).',src:'pe3-cp:11'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'For an ion, Ka = 5.6 × 10⁻¹¹ and Kb = 1.8 × 10⁻⁴ in water. How does it mainly act?',choices:['As a base, because Ka > Kb','As a base, because Kb > Ka','As an acid, because Ka > Kb','As an acid, because Kb > Ka'],ans:1,exp:'Compare the two constants: **the larger one wins**. Kb (10⁻⁴) ≫ Ka (10⁻¹¹), so it acts as a **base**. (This is bicarbonate, HCO₃⁻.)',src:'pe3-cp:12'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Zn + I₂ → ZnI₂. With 0.0079 mol I₂ and 0.030 mol Zn, and unreacted zinc left over, which is limiting?',choices:['Iodine','Zinc','Both run out together','The solvent'],ans:0,exp:'1:1 ratio, and there\'s **less I₂** than Zn. The clue "unreacted zinc was recovered" also tells you zinc was in **excess**, so iodine ran out first.',src:'pe3-cp:13'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'On a reaction energy diagram, how is the activation energy defined?',choices:['Reactants minus products','Products minus reactants','Activated complex minus products','Activated complex minus reactants'],ans:3,exp:'**Ea = top of the hill (transition state) − reactants.** Products minus reactants is ΔH, which is a different quantity.',src:'pe3-cp:14'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'In its ground state, zinc (Z = 30) has:',choices:['filled 3d and filled 4s','half-filled 3d and filled 4s','filled 3d and half-filled 4s','half-filled 3d and half-filled 4s'],ans:0,exp:'Zn = **[Ar] 4s² 3d¹⁰**: both full. (Cr and Cu are the exceptions that end up with 4s¹.)',src:'pe3-cp:15'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Zinc metal reacts with I₂ to form Zn²⁺ and I⁻. What type of reaction is this?',choices:['Acid–base neutralization','Precipitate formation','Oxidation–reduction','Chelate formation'],ans:2,exp:'Zn goes 0 → +2 (oxidized) and I goes 0 → −1 (reduced). **Any change in oxidation state = redox.**',src:'pe3-cp:16'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'A "cold" plasma is about 35 °C. Which kelvin range contains that temperature?',choices:['393–423 K','363–373 K','303–313 K','273–283 K'],ans:2,exp:'**K = °C + 273**, so 35 °C = 308 K. Body temperature (37 °C) ≈ 310 K is a handy anchor.',src:'pe3-cp:17'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4A',q:'A voltage pulse is on for 500 ns, then off for 500 ns, repeating. What is its period?',choices:['2000 ns','1500 ns','1000 ns','500 ns'],ans:2,exp:'**Period = time for one full cycle** (on + off) = 500 + 500 = 1000 ns. The on-time alone is the pulse width, a common trap.',src:'pe3-cp:18'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4D',q:'A lamp emits UV from 200 to 300 nm. What is the MAXIMUM photon energy? (hc ≈ 2.0 × 10⁻²⁵ J·m)',choices:['7 × 10⁻¹⁶ J','5 × 10⁻¹⁷ J','3 × 10⁻¹⁷ J','1 × 10⁻¹⁸ J'],ans:3,exp:'E = hc/λ, so **shortest wavelength = highest energy**. 2.0 × 10⁻²⁵ ÷ 200 × 10⁻⁹ = 1 × 10⁻¹⁸ J. UV photons sit around 10⁻¹⁸ J.',src:'pe3-cp:19'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4C',q:'The electric field between two flat electrodes is uniform. What does that mean for the field lines?',choices:['Closer together near the positive plate','They cross halfway between the plates','Closer together near the negative plate','Evenly spaced everywhere between the plates'],ans:3,exp:'Line spacing shows field strength. **Uniform field = same strength everywhere = evenly spaced, parallel lines.** Field lines never cross.',src:'pe3-cp:20'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'A solution contains 72 g/L glucose. How much glucose is in a 2 μL drop?',choices:['3.6 × 10⁻⁷ g','1.4 × 10⁻⁴ g','3.6 × 10⁻⁴ g','1.4 × 10⁻¹ g'],ans:1,exp:'2 μL = **2 × 10⁻⁶ L**. 72 g/L × 2 × 10⁻⁶ L = 1.44 × 10⁻⁴ g. Convert μL to L before multiplying.',src:'pe3-cp:21'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'Glucose oxidase converts glucose into gluconolactone by removing electrons. Which enzyme class is it?',choices:['Transferase','Isomerase','Oxidoreductase','Hydrolase'],ans:2,exp:'Anything that **oxidizes or reduces** its substrate (moves electrons) is an **oxidoreductase**. Names ending in "-oxidase" or "-dehydrogenase" are the giveaway.',src:'pe3-cp:22'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4C',q:'Each glucose molecule gives up 2 electrons. If a sensor measures 0.66 μmol of electrons, what mass of glucose reacted? (180 μg/μmol)',choices:['20 μg','60 μg','90 μg','270 μg'],ans:1,exp:'Electrons → glucose: 0.66 ÷ 2 = 0.33 μmol. × 180 μg/μmol ≈ **60 μg**. Always apply the **electrons-per-molecule** ratio first.',src:'pe3-cp:23'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'An enzyme oxidizes glucose by removing two hydrogens. Which cofactor accepts them?',choices:['FAD','NADH','H₂O','Acetyl-CoA'],ans:0,exp:'An oxidation needs an **oxidizing agent**: FAD (→ FADH₂). NADH is already reduced, so it is an electron **donor**, not an acceptor.',src:'pe3-cp:24'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Which ring pattern identifies a steroid, the kind of molecule a steroid hormone receptor binds?',choices:['Two fused six-membered rings','A single benzene ring with a side chain','A long unbranched chain','Four fused rings (three 6-rings and one 5-ring)'],ans:3,exp:'Steroids (cholesterol, cortisol, estrogen, testosterone) share the **6-6-6-5 fused four-ring core**. Spot it in a structure question and you\'re done.',src:'pe3-cp:25'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'A phosphate buffer (pKa 7.2) reads pH 7.6, but you need pH 7.2. What should you do?',choices:['Add more of the disodium (basic) form','Add a small amount of NaOH solution','Add more of the monosodium (acidic) form','Dilute it with distilled water'],ans:2,exp:'**pH = pKa + log([base]/[acid])**. To lower the pH to equal the pKa, make [acid] = [base] by adding more **acid form (H₂PO₄⁻)**. Dilution barely changes a buffer\'s pH.',src:'pe3-cp:26'},
  {s:'Practice Exam 3: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'Two amino acids form a peptide bond. What is the mass of the small molecule released?',choices:['17 amu','18 amu','32 amu','44 amu'],ans:1,exp:'Peptide bond formation is a **condensation**: it releases **water (H₂O = 18 amu)**. Hydrolysis is the reverse, using up water.',src:'pe3-cp:27'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'Which condition is NOT needed for good Michaelis–Menten kinetics data?',choices:['Measuring initial velocity at steady state','Constant pH at every [S]','Much less enzyme than substrate','Letting the reaction reach equilibrium first'],ans:3,exp:'Michaelis–Menten plots use **initial rates (V₀)**. At equilibrium the net rate is zero, so measuring then would ruin the data.',src:'pe3-cp:28'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'An enzyme uses FAD at intermediate steps, but FAD is regenerated each cycle. Does FAD appear in the overall balanced equation?',choices:['Yes, as a reactant','Yes, as a product','No, because it is regenerated','Only if O₂ is a reactant'],ans:2,exp:'Like a catalyst, anything **used and then regenerated cancels** from the net equation. Only the species that are consumed or made overall (here NADPH, O₂ → NADP⁺, H₂O₂) remain.',src:'pe3-cp:29'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'In a reaction, O₂ becomes H₂O. What happens to oxygen?',choices:['It is oxidized from 0 to +2','It is reduced from 0 to −2','It is oxidized from −2 to 0','Its oxidation state stays the same'],ans:1,exp:'Oxygen in O₂ is **0**; in H₂O it\'s **−2**. A decrease in oxidation number = **reduction**, so O₂ is the oxidizing agent.',src:'pe3-cp:32'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Lysine and similar amino acids have side-chain amines that are protonated in water. How are they classified?',choices:['Acidic and hydrophobic','Basic and hydrophilic','Neutral and hydrophilic','Neutral and hydrophobic'],ans:1,exp:'A side-chain **–NH₂ picks up H⁺ → –NH₃⁺**: that makes it **basic** and charged, so **hydrophilic**. The basic amino acids are Lys, Arg and His.',src:'pe3-cp:33'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'What is [OH⁻] in a solution at pH 10?',choices:['10⁻¹⁰ M','10⁻⁶ M','10⁻⁴ M','10⁻² M'],ans:2,exp:'**pH + pOH = 14** → pOH = 4 → [OH⁻] = 10⁻⁴ M. 10⁻¹⁰ is [H⁺], the trap answer.',src:'pe3-cp:34'},
  {s:'Practice Exam 3: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'An enzyme oxidizes phenol side chains into radicals. Which amino acid side chain could it act on?',choices:['Lysine','Leucine','Tyrosine','Glutamine'],ans:2,exp:'**Tyrosine is the amino acid with a phenol** (a benzene ring with OH). Phenylalanine has the ring but no OH.',src:'pe3-cp:36'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Which atom in a protein most likely binds (coordinates) a Ca²⁺ ion?',choices:['Hydrogen','Carbon','Nitrogen','Oxygen'],ans:3,exp:'A metal cation needs a **Lewis base with lone pairs and negative charge**: the carboxylate O of Asp/Glu or a backbone C=O oxygen. Amide nitrogens share their lone pair through resonance.',src:'pe3-cp:37'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Heme\'s porphyrin ring is built from four units of which ring?',choices:['Pyrrole (5-membered, one N)','Benzene (6-membered, no N)','Pyridine (6-membered, one N)','Furan (5-membered, one O)'],ans:0,exp:'**Heme = porphyrin = 4 pyrroles** linked in a big ring, with Fe in the center held by the four N atoms.',src:'pe3-cp:38'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4C',q:'A material\'s conductivity is 5.0 × 10⁻³ (Ω·cm)⁻¹. What is its resistivity?',choices:['0.002 Ω·cm','50 Ω·cm','200 Ω·cm','500 Ω·cm'],ans:2,exp:'**Resistivity = 1 ÷ conductivity** = 1 ÷ 0.005 = 200 Ω·cm. The units, (Ω·cm)⁻¹, tell you to flip it.',src:'pe3-cp:39'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'Cytosine is first methylated, then its new CH₃ is oxidized to CH₂OH. Which enzyme classes are needed?',choices:['Transferase, then oxidoreductase','Hydrolase, then ligase','Oxidoreductase, then hydrolase','Transferase, then ligase'],ans:0,exp:'**Adding a methyl group = transferase** (methyltransferase). **Oxidizing it = oxidoreductase.** Name each step\'s chemistry, then match it to a class.',src:'pe3-cp:40'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'What is ΔG°′ for a DNA structure unfolding (native ⇌ unfolded)?',choices:['−RT ln([native]/[unfolded])','−RT ln([unfolded]/[native])','−RT·e^([unfolded]/[native])','+RT ln([unfolded]/[native])'],ans:1,exp:'**ΔG° = −RT ln K**, with K = products/reactants = [unfolded]/[native]. Write the reaction direction first, then build K.',src:'pe3-cp:41'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'On an unfolding curve (fraction folded vs. pH), what shows HIGH cooperativity?',choices:['A very steep transition','A very gradual transition','A transition at high pH','No transition at all'],ans:0,exp:'Cooperative = **all-or-nothing**: the whole structure flips over a narrow range, so the curve is **steep**. The midpoint\'s position (pK) is a separate property.',src:'pe3-cp:42'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biology',aamc:'5D',q:'A DNA strand contains no guanine. Which nucleoside will its complementary strand lack?',choices:['Deoxyadenosine','Deoxycytidine','Deoxyguanosine','Deoxythymidine'],ans:1,exp:'**G pairs with C.** With no G to pair with, the complement has no **C (deoxycytidine)**. A↔T and G↔C.',src:'pe3-cp:44'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5C',q:'A cation-exchange column binds positively charged proteins. When is a protein positively charged?',choices:['When buffer pH is below its pI','When buffer pH is above its pI','When buffer pH equals its pI','Only when pH is above 11'],ans:0,exp:'**Below the pI, a protein has extra H⁺ → net positive** → it sticks to a cation exchanger. Above the pI it is negative. At the pI it is neutral.',src:'pe3-cp:45'},
  {s:'Practice Exam 3: Chem/Phys',disc:'biochemistry',aamc:'5C',q:'Dextran, a glucose polymer, is used as column material. How does it mainly interact with proteins?',choices:['Aromatic stacking','Hydrophobic interactions','Salt bridges','Hydrogen bonding'],ans:3,exp:'A polysaccharide is covered in **–OH groups**, which **hydrogen bond**. It has no rings with π systems, no grease and no charges.',src:'pe3-cp:46'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Which halogen has the highest first ionization energy?',choices:['Iodine','Bromine','Chlorine','Fluorine'],ans:3,exp:'Ionization energy **increases up a group** (smaller atom, electrons held tighter). Fluorine is at the top of the halogens.',src:'pe3-cp:47'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4A',q:'An object starts from rest with constant acceleration. A graph shows d = 36 at t = 6 and d = 100 at t = 10. What is the relationship?',choices:['d ∝ 1/t','d ∝ 1/t²','d ∝ t','d ∝ t²'],ans:3,exp:'6² = 36 and 10² = 100, so **d ∝ t²** (d = ½at² from rest). Test the numbers against each choice.',src:'pe3-cp:48'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4D',q:'An ultrasound wave passes from water into body tissue. Which property stays the same?',choices:['Frequency','Wave speed','Amplitude','Wavelength'],ans:0,exp:'**Frequency is set by the source** and never changes between media. Speed changes, so wavelength changes with it (v = fλ). Amplitude drops as energy is absorbed.',src:'pe3-cp:49'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4B',q:'Fluid moves at 0.30 mm/s through an opening of area 2.5 × 10⁴ μm². What is the volume flow rate?',choices:['4.5 × 10⁶ μm³/s','7.5 × 10⁶ μm³/s','1.2 × 10⁷ μm³/s','4.5 × 10⁷ μm³/s'],ans:1,exp:'**Q = A × v.** Convert v: 0.30 mm/s = 300 μm/s. 2.5 × 10⁴ × 300 = 7.5 × 10⁶ μm³/s.',src:'pe3-cp:50'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4D',q:'A 2.3 MHz ultrasound wave travels through tissue at 1500 m/s. About what is its wavelength?',choices:['34.5 mm','6.5 mm','1.5 mm','0.65 mm'],ans:3,exp:'**λ = v/f** = 1500 ÷ 2.3 × 10⁶ ≈ 6.5 × 10⁻⁴ m = 0.65 mm. Remember M = 10⁶.',src:'pe3-cp:51'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4B',q:'A vessel of area A at speed v feeds n capillaries, each of area a. What is the speed u in each capillary?',choices:['u = Av/(na)','u = nav/A','u = Ana/v','u = v/(Ana)'],ans:0,exp:'**Continuity: flow in = flow out.** A·v = n·a·u, so u = Av/(na). More total area → slower flow.',src:'pe3-cp:52'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'What is the Ksp expression for CaCO₃(s) ⇌ Ca²⁺ + CO₃²⁻?',choices:['[Ca²⁺][CO₃²⁻]/[CaCO₃]','[Ca²⁺][CO₃²⁻]','[CaCO₃]/([Ca²⁺][CO₃²⁻])','[Ca²⁺]²[CO₃²⁻]²'],ans:1,exp:'**Solids are left out of K expressions.** Ksp = product of dissolved ions, each raised to its coefficient (here 1).',src:'pe3-cp:53'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Calcium and magnesium belong to which group?',choices:['Alkali metals (Group 1)','Metalloids (staircase)','Alkaline earth metals','Halogens (Group 17)'],ans:2,exp:'**Group 2 = alkaline earth metals** (Be, Mg, Ca…), forming 2+ ions. Group 1 is the alkali metals (Na, K).',src:'pe3-cp:54'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'If a reaction is spontaneous under standard conditions, K must be:',choices:['greater than 1','equal to ΔG','less than 1','equal to zero'],ans:0,exp:'**ΔG° = −RT ln K.** Negative ΔG° requires ln K > 0, so **K > 1** (products favored).',src:'pe3-cp:55'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'In a water softener, Ca²⁺ + 2 Na-resin ⇌ Ca-resin + 2Na⁺. What shifts it to the LEFT (regenerating the resin)?',choices:['Adding more resin','Adding Ca²⁺','Adding lots of Na⁺','Adding more resin anion sites'],ans:2,exp:'**Le Châtelier:** adding a **product (Na⁺)** pushes the reaction back toward reactants. This is why softeners are flushed with salt water.',src:'pe3-cp:56'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'Which molecule has an octahedral shape?',choices:['SF₆','CBr₄','XeF₄','BrF₃'],ans:0,exp:'**SF₆: six bonds, no lone pairs → octahedral.** XeF₄ has six domains too, but two are lone pairs, so its shape is square planar. CBr₄ is tetrahedral.',src:'pe3-cp:57'},
  {s:'Practice Exam 3: Chem/Phys',disc:'physics',aamc:'4B',q:'Air is pumped out of a tall tube standing in water, and atmospheric pressure (10⁵ Pa) pushes water up into it. How high does the water rise?',choices:['1 m','5 m','10 m','20 m'],ans:2,exp:'**P = ρgh** → h = 10⁵ ÷ (1000 × 10) = **10 m**. One atmosphere holds up about 10 m of water (or 760 mm of mercury).',src:'pe3-cp:58'},
  {s:'Practice Exam 3: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Which period-2 element forms a covalent network solid in its standard state?',choices:['Carbon','Phosphorus','Oxygen','Iodine'],ans:0,exp:'**Carbon (diamond, graphite)** forms a giant web of covalent bonds. Phosphorus and iodine aren\'t in period 2, and oxygen is a gas.',src:'pe3-cp:59'},
  // ── Practice Exam 4 · Chem/Phys (built 2026-11-11) ──
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'A decomposition is endothermic and does NOT happen at 900 K. How do ΔH and TΔS compare at that temperature?',choices:['ΔH > 0 and ΔH < TΔS','ΔH > 0 and ΔH > TΔS','ΔH < 0 and ΔH < TΔS','ΔH < 0 and ΔH > TΔS'],ans:1,exp:'Not spontaneous → **ΔG = ΔH − TΔS > 0**, so ΔH must be **bigger** than TΔS. At a higher T, TΔS grows and eventually wins.',src:'pe4-cp:1'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'What is the equilibrium constant for CaCO₃(s) ⇌ CaO(s) + CO₂(g)?',choices:['K = [CaO]','K = [CaCO₃]','K = [CO₂]','K = [CaO][CaCO₃]'],ans:2,exp:'**Pure solids (and liquids) are left out of K.** Only the gas remains: K = [CO₂] (or P_CO₂).',src:'pe4-cp:2'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'In NH₃ + H⁺ → NH₄⁺, what happens to nitrogen\'s oxidation state?',choices:['It changes from −3 to −4','It changes from 0 to +1','It stays at −3','It stays at +1'],ans:2,exp:'This is **acid–base**, not redox: H⁺ is added, but N keeps −3 in both NH₃ and NH₄⁺. **Proton transfers don\'t change oxidation states.**',src:'pe4-cp:3'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'A reaction produces 1 mol of gas. What volume does it occupy at STP?',choices:['22.4 L','44.8 L','67.2 L','89.6 L'],ans:0,exp:'**1 mol of ideal gas at STP (0 °C, 1 atm) = 22.4 L.** Count only the moles of the gas you\'re asked about.',src:'pe4-cp:4'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'4D',q:'Why must a sample cuvette and a reference cuvette have identical optical properties?',choices:['So absorbance differences come only from the sample','So the glass walls absorb less light','So the wavelength is more exact','So the solutions absorb more light'],ans:0,exp:'A matched reference **cancels out everything except the analyte**. Any difference in the glass would show up as false absorbance.',src:'pe4-cp:5'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4D',q:'Light of 625 nm is absorbed. About what is the photon energy? (hc ≈ 2.0 × 10⁻²⁵ J·m; 1 eV = 1.6 × 10⁻¹⁹ J)',choices:['1 eV','2 eV','3 eV','4 eV'],ans:1,exp:'E = hc/λ ≈ 2.0 × 10⁻²⁵ ÷ 6.25 × 10⁻⁷ ≈ 3.2 × 10⁻¹⁹ J ÷ 1.6 × 10⁻¹⁹ = **2 eV**. Shortcut: **E (eV) ≈ 1240 ÷ λ (nm)**.',src:'pe4-cp:6'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'A sample reads above the highest standard on a calibration curve. What gives the most reliable reading?',choices:['Adding more enzyme','Raising the oxygen pressure','Using less color reagent','Diluting the sample'],ans:3,exp:'Readings are reliable only **inside** the standards (interpolation). **Dilute** the sample into range, then multiply by the dilution factor.',src:'pe4-cp:8'},
  {s:'Practice Exam 4: Chem/Phys',disc:'organic_chem',aamc:'5C',q:'Why can 1-chlorobutane and 1-butanol be separated by fractional distillation?',choices:['Both are polar','Both are nonpolar','1-Chlorobutane boils at a much higher temperature','1-Chlorobutane boils at a much lower temperature'],ans:3,exp:'Distillation separates by **boiling point**. 1-Butanol **hydrogen bonds**, so it boils much higher. The alkyl chloride distills off first.',src:'pe4-cp:9'},
  {s:'Practice Exam 4: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'Which oxidation is unlikely to occur?',choices:['Primary alcohol → aldehyde','Tertiary alcohol → ketone','Aldehyde → carboxylic acid','Secondary alcohol → ketone'],ans:1,exp:'Oxidation needs an **H on the carbinol carbon**. A tertiary alcohol has none, so it would have to break a C–C bond. 1° → aldehyde → acid; 2° → ketone.',src:'pe4-cp:10'},
  {s:'Practice Exam 4: Chem/Phys',disc:'organic_chem',aamc:'5B',q:'CH₃–CH=C(CH₃)–CH₂CH₃ has its two higher-priority groups (CH₃ on C2, ethyl on C3) on the same side. What is its name?',choices:['(Z)-3-methylpent-2-ene','(E)-3-methylpent-2-ene','(Z)-3-ethylbut-2-ene','(E)-3-ethylbut-2-ene'],ans:0,exp:'**Longest chain = 5 carbons** (pentene, not butene), numbered so C=C starts at C2. Higher priorities on the **same side = Z** (zusammen).',src:'pe4-cp:11'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4A',q:'Vectors of 8 units and 5 units can point at any angle to each other. Which magnitude can their sum NOT have?',choices:['2 units','5 units','8 units','12 units'],ans:0,exp:'The sum ranges from **|8 − 5| = 3** (opposite) to **8 + 5 = 13** (same direction). Anything outside 3–13 is impossible.',src:'pe4-cp:12'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4D',q:'A nearsighted eye focuses too strongly. To correct it, laser surgery flattens the cornea. What does that change?',choices:['It raises the cornea\'s density','It increases the radius of curvature','It raises the refractive index','It thickens the cornea\'s center'],ans:1,exp:'**Flatter surface = larger radius of curvature = weaker focusing** (longer focal length). Density and refractive index are properties of the tissue, which surgery doesn\'t change.',src:'pe4-cp:13'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4C',q:'8.0 kV is applied across a 4.0 mm gap. What is the electric field?',choices:['2.0 × 10⁶ V/m','4.0 × 10⁵ V/m','6.0 × 10⁴ V/m','8.0 × 10³ V/m'],ans:0,exp:'**E = V/d** = 8000 V ÷ 0.004 m = 2.0 × 10⁶ V/m. Convert mm to m first.',src:'pe4-cp:14'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4A',q:'A laser fires one pulse every 250 ms. What is the pulse frequency?',choices:['0.4 Hz','4.0 Hz','25 Hz','250 Hz'],ans:1,exp:'**f = 1/T** = 1 ÷ 0.250 s = 4 Hz. Convert ms to seconds first; frequency and period are always reciprocals.',src:'pe4-cp:15'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'5E',q:'Why use a pulsed laser instead of a continuous one on living tissue?',choices:['The tissue absorbs more energy','The refractive index changes','More area is exposed','The tissue stays cooler on average'],ans:3,exp:'Between pulses, heat can **dissipate**, so the **average temperature stays lower** and nearby tissue isn\'t burned.',src:'pe4-cp:16'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'Which intermolecular forces act between NH₃ molecules in the gas?',choices:['Only dipole–dipole forces','Only London dispersion forces','Both dipole–dipole and London forces','Neither of these forces'],ans:2,exp:'**Every molecule has London forces.** NH₃ is also polar (and can H-bond, a strong dipole–dipole force). So "dipole–dipole only" is never right.',src:'pe4-cp:17'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'For 10 M NH₃, Kb ≈ 1.8 × 10⁻⁵. About what is [NH₄⁺] at equilibrium?',choices:['0.001 M','0.01 M','0.1 M','1 M'],ans:1,exp:'x² = Kb × C = 1.8 × 10⁻⁵ × 10 ≈ 1.8 × 10⁻⁴, so **x ≈ √(Kb·C) ≈ 0.013 M**. Weak bases barely ionize.',src:'pe4-cp:18'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'A can filled with NH₃ gas crushes when its gas dissolves in water. What would happen with CH₄ instead?',choices:['It crushes; polar CH₄ dissolves','It crushes; nonpolar CH₄ dissolves','No crush; polar CH₄ won\'t dissolve','No crush; nonpolar CH₄ won\'t dissolve'],ans:3,exp:'**CH₄ is nonpolar** (symmetric), so it barely dissolves in water. No gas leaves the can, so pressure doesn\'t drop. NH₃ crushes the can because it\'s very water-soluble.',src:'pe4-cp:19'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Ca(OH)₂ and CaCl₂ are compounds of which kind of element?',choices:['An alkali metal','An alkaline earth metal','A metalloid','A transition metal'],ans:1,exp:'**Ca is in Group 2 → alkaline earth metal**, forming Ca²⁺. Alkali metals (Group 1) form 1+ ions.',src:'pe4-cp:20'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Convert 0.6 nM into μM.',choices:['6 × 10⁻¹⁰ μM','6 × 10⁻⁷ μM','6 × 10⁻⁴ μM','6 × 10⁻² μM'],ans:2,exp:'**1 μM = 1000 nM**, so 0.6 nM = 0.0006 μM = 6 × 10⁻⁴ μM. Going to a bigger unit makes the number smaller.',src:'pe4-cp:22'},
  {s:'Practice Exam 4: Chem/Phys',disc:'organic_chem',aamc:'5B',q:'What bonds connect the C and O in a carbonyl group?',choices:['One σ bond only','One σ bond and one π bond','One π bond only','One σ bond and two π bonds'],ans:1,exp:'C=O is a **double bond = 1 σ + 1 π**. The first bond between two atoms is always σ; a triple bond is 1 σ + 2 π.',src:'pe4-cp:25'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'Which atom gains one electron most readily?',choices:['Argon','Bromine','Cobalt','Sodium'],ans:1,exp:'**Halogens (Group 17) are one electron short of a full shell**, so they grab one readily. Noble gases (Ar) are already full; metals (Na, Co) lose electrons.',src:'pe4-cp:26'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'5E',q:'On a phase diagram, a point lies on the line between the solid and gas regions. What does it represent?',choices:['A boiling point','The critical point','A melting point','A sublimation point'],ans:3,exp:'**Solid ↔ gas = sublimation.** Solid–liquid line = melting; liquid–gas line = boiling; the critical point is where the liquid–gas line ends.',src:'pe4-cp:27'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4E',q:'Which electron transition gives off the photon with the LONGEST wavelength?',choices:['The one between the two closest levels','The one between the two farthest levels','The one ending at the ground state','The one starting at the highest level'],ans:0,exp:'**E = hc/λ**, so the longest wavelength means the **smallest energy gap**: the transition between the **closest** levels.',src:'pe4-cp:28'},
  {s:'Practice Exam 4: Chem/Phys',disc:'organic_chem',aamc:'5A',q:'A nitrogen is bonded to three carbons, none of which is a C=O. What is the functional group?',choices:['An amide','An amine','An imine','A carbamate'],ans:1,exp:'**N with single bonds to C or H only = amine.** N next to C=O = amide; C=N double bond = imine; N–C(=O)–O = carbamate.',src:'pe4-cp:29'},
  {s:'Practice Exam 4: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'NaBH₄ reduces a ketone to an alcohol, and that OH then attacks an ester in the same molecule. What forms?',choices:['A lactone (cyclic ester)','An acetal','A lactam (cyclic amide)','An ether'],ans:0,exp:'An **intramolecular ester** is a **lactone**. γ-Hydroxy esters cyclize easily into 5-membered lactones. A lactam would need an amine instead of an OH.',src:'pe4-cp:30'},
  {s:'Practice Exam 4: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'Base is added to an ammonium salt (R₂NH₂⁺ Cl⁻) before an SN2 step. Why?',choices:['To help dissolve the alkyl halide','To remove an α-hydrogen from the ester','To free the amine\'s lone pair to attack','To swap the chloride ion for carbonate'],ans:2,exp:'A protonated amine has **no free lone pair**, so it can\'t attack. Base removes the H⁺ → the neutral amine becomes a **nucleophile**.',src:'pe4-cp:32'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'An inhibitor can bind an enzyme both before and after the substrate binds, without blocking substrate binding. What type is it?',choices:['Competitive','Mixed','Product','Irreversible'],ans:1,exp:'Binds **both E and ES → mixed** (noncompetitive if it binds both equally). Competitive inhibitors bind only free E, at the active site.',src:'pe4-cp:34'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'An enzyme must bind substrate A before it can bind substrate B. What is the binding mechanism called?',choices:['Random order','Ordered','Ping-pong','Double displacement'],ans:1,exp:'**Fixed sequence = ordered.** Random = either can bind first. Ping-pong (double displacement) = the first product leaves before the second substrate binds.',src:'pe4-cp:35'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'A drug\'s strongest contacts with an enzyme come from valine and phenylalanine side chains. What interaction is that?',choices:['Covalent bonding','Hydrogen bonding','Ionic bonding','Hydrophobic interactions'],ans:3,exp:'**Val and Phe are nonpolar**: no charges and no H-bond donors. They make **hydrophobic** contacts.',src:'pe4-cp:36'},
  {s:'Practice Exam 4: Chem/Phys',disc:'organic_chem',aamc:'5B',q:'A molecule has 4 C=C bonds, 1 C=O and 1 C≡N. How many π bonds does it have?',choices:['5','6','7','8'],ans:2,exp:'Each **double bond = 1 π**, each **triple bond = 2 π**: 4 + 1 + 2 = 7.',src:'pe4-cp:37'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'4D',q:'A = εbc. With A = 0.7, ε ≈ 1400 M⁻¹cm⁻¹ and b = 1 cm, what is c?',choices:['0.50 μM','500 μM','5 mM','500 mM'],ans:1,exp:'c = A/(εb) = 0.7 ÷ 1400 = **5 × 10⁻⁴ M = 500 μM**.',src:'pe4-cp:38'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'4D',q:'A detector can\'t read high absorbances. What fixes this for the samples that absorb most strongly?',choices:['Dilute them or shorten the path length','Concentrate them or lengthen the path','Use a wider cuvette for them','Run them at a higher temperature'],ans:0,exp:'A = εbc: absorbance drops if you lower **c (dilute)** or **b (shorter path)**. Apply it only to the strongly absorbing samples.',src:'pe4-cp:39'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'Tris has a pKa of 8.1. Over what pH range does it buffer well?',choices:['About 7.1 to 9.1','About 6.1 to 10.1','Only at exactly 8.1','About 2 to 14'],ans:0,exp:'A buffer works within about **pKa ± 1**. Outside that, one form runs out.',src:'pe4-cp:40'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'An aspartate side chain attacks a phosphate group, forming a covalent enzyme intermediate. Which atom does it attack?',choices:['The phosphorus','A phosphate oxygen','The substrate\'s carbon','A metal ion'],ans:0,exp:'Nucleophiles attack the **electrophile**: the electron-poor **phosphorus** in the center, like attacking a carbonyl carbon. A leaving group departs.',src:'pe4-cp:41'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'What is [H₃O⁺] at pH 6?',choices:['0.01 μM','0.1 μM','1.0 μM','100 μM'],ans:2,exp:'[H⁺] = 10⁻ᵖᴴ = 10⁻⁶ M = **1.0 μM** (micro = 10⁻⁶).',src:'pe4-cp:42'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'Which quantity measures an enzyme\'s catalytic efficiency?',choices:['kcat ÷ KM','KM alone','Vmax ÷ kcat','KM ÷ kcat'],ans:0,exp:'**Catalytic efficiency = kcat/KM.** kcat (turnover) tracks Vmax; KM tracks affinity (lower KM = tighter binding). If kcat falls, efficiency falls too.',src:'pe4-cp:43'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4B',q:'What lets small insects walk on water?',choices:['Hydrostatic pressure','Viscosity','Buoyancy','Surface tension'],ans:3,exp:'Water molecules at the surface **cohere** through hydrogen bonds, forming an elastic "skin": **surface tension**. The insect doesn\'t sink in, so buoyancy isn\'t what holds it up.',src:'pe4-cp:44'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4E',q:'An isotope has a 2-hour half-life. After 6 hours, 24 g remains. What was the starting amount?',choices:['3 g','4 g','144 g','192 g'],ans:3,exp:'6 h = 3 half-lives, so 1/8 remains. **Work backward: 24 × 2 × 2 × 2 = 192 g.** 3 g is the trap of going forward.',src:'pe4-cp:45'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4D',q:'Light passing a thin thread makes alternating bright and dark fringes on a screen. What causes this?',choices:['Refraction','Polarization','Diffraction','Reflection'],ans:2,exp:'Light **bends around a small obstacle or slit** and the waves interfere: **diffraction**. Fringes appear when the obstacle is about the size of the wavelength.',src:'pe4-cp:46'},
  {s:'Practice Exam 4: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'Which saturated fatty acid is most soluble in water?',choices:['CH₃(CH₂)₁₀COOH','CH₃(CH₂)₁₂COOH','CH₃(CH₂)₁₄COOH','CH₃(CH₂)₁₆COOH'],ans:0,exp:'All have one polar COOH. **Shorter nonpolar tail → more water-soluble.** Choose the smallest subscript.',src:'pe4-cp:47'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Which tautomers of guanine and thymine dominate at physiological pH?',choices:['Keto G and keto T','Keto G and enol T','Enol G and keto T','Enol G and enol T'],ans:0,exp:'Normal DNA bases sit in their **keto (C=O, N–H)** forms. Rare enol tautomers cause mispairing (mutations).',src:'pe4-cp:48'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4E',q:'³²P undergoes β⁻ decay. What atom is left?',choices:['Silicon','Aluminum','Sulfur','Chlorine'],ans:2,exp:'**β⁻: neutron → proton**, so Z rises by 1. P (15) → **S (16)**; mass number stays 32.',src:'pe4-cp:49'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'An enzyme\'s Asp binds metal ions through its carboxylate. Which mutation most likely keeps the enzyme active?',choices:['Asp → Ala','Asp → Glu','Asp → Lys','Asp → Phe'],ans:1,exp:'**Glu also has a carboxylate (–COO⁻)**, just one CH₂ longer: a **conservative** swap. Ala and Phe lose the charge; Lys flips it to positive.',src:'pe4-cp:50'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'How many hydrogen bonds hold a normal G–C pair and a normal A–T pair together?',choices:['G–C: 3, A–T: 2','G–C: 2, A–T: 3','G–C: 2, A–T: 2','G–C: 3, A–T: 3'],ans:0,exp:'**G–C = 3 H-bonds; A–T = 2.** A mismatch shaped like G–C has 3; one shaped like A–T (a "wobble") has 2.',src:'pe4-cp:51'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'A DNA polymerase needs a divalent metal ion. Which metal could NOT fill this role?',choices:['Zinc','Iron','Magnesium','Sodium'],ans:3,exp:'**Na only forms Na⁺** (Group 1, one valence electron). Mg²⁺ is the classic polymerase cofactor; Zn and Fe can form 2+ ions.',src:'pe4-cp:52'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4A',q:'A capacitor stores 400 J. To what height would a 5 kg stone need to be lifted to store the same energy? (g ≈ 10 m/s²)',choices:['4 m','8 m','16 m','32 m'],ans:1,exp:'**PE = mgh** → h = 400 ÷ (5 × 10) = 8 m.',src:'pe4-cp:53'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4C',q:'A battery is rated at 4.2 A·h. About how much charge can it deliver?',choices:['4.2 C','38 C','15,000 C','136,000 C'],ans:2,exp:'**Q = I × t** = 4.2 A × 3600 s ≈ 15,000 C. An amp-hour is a unit of charge; convert hours to seconds.',src:'pe4-cp:54'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4A',q:'20 g of blood speeds up from 25 cm/s to 35 cm/s in 0.10 s. What average force acts on it?',choices:['0.020 N','0.20 N','20 N','2000 N'],ans:0,exp:'a = Δv/Δt = 0.10 m/s ÷ 0.10 s = 1 m/s². **F = ma** = 0.020 kg × 1 = 0.020 N. Convert g → kg and cm → m.',src:'pe4-cp:55'},
  {s:'Practice Exam 4: Chem/Phys',disc:'physics',aamc:'4C',q:'Why is the electric field inside a conductor at equilibrium zero?',choices:['All of its electrons are bound to atoms','Free charges shift until their field cancels any outside field','The conductor is always uncharged','Electric fields can\'t pass through metals'],ans:1,exp:'Mobile electrons **move until the net internal field is zero**, and any excess charge sits on the surface. This is how a Faraday cage works.',src:'pe4-cp:56'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biology',aamc:'4B',q:'Blood pressure is 135/90 mmHg. What is the mean arterial pressure, MAP = (2 × diastolic + systolic) ÷ 3?',choices:['85 mmHg','90 mmHg','105 mmHg','110 mmHg'],ans:2,exp:'(2 × 90 + 135) ÷ 3 = 315 ÷ 3 = **105 mmHg**. Diastolic is counted twice because the heart spends more time in diastole.',src:'pe4-cp:57'},
  {s:'Practice Exam 4: Chem/Phys',disc:'biology',aamc:'4C',q:'Which happens FIRST when an action potential is generated?',choices:['Voltage-gated Na⁺ channels open at the axon hillock','Hyperpolarization opens K⁺ channels','Graded potentials travel along the axon','Ca²⁺ entry triggers transmitter release'],ans:0,exp:'Order: reach threshold at the hillock → **Na⁺ channels open (depolarize)** → K⁺ channels open (repolarize) → the signal travels → Ca²⁺ at the terminal → release.',src:'pe4-cp:58'},
  {s:'Practice Exam 4: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'How much heat raises 2 kg of water from 20 °C to 70 °C? (c = 4.2 kJ/kg·°C)',choices:['220 kJ','320 kJ','420 kJ','520 kJ'],ans:2,exp:'**q = mcΔT** = 2 kg × 4.2 kJ/kg·°C × 50 °C = 420 kJ. ΔT is the change (70 − 20), not the final temperature.',src:'pe4-cp:59'},
  // ── Practice Exam 6 · Chem/Phys (built 2026-11-11) ──
  {s:'Practice Exam 6: Chem/Phys',disc:'organic_chem',aamc:'4D',q:'A reaction turns a ketone into an alcohol. Which new IR band proves the alcohol formed?',choices:['A broad band at 3000–4000 cm⁻¹','A sharp band near 1700 cm⁻¹','A band at 2000–2300 cm⁻¹','A band at 650–1000 cm⁻¹'],ans:0,exp:'**O–H stretch = broad, about 3200–3600 cm⁻¹.** The C=O band (sharp, ~1700) would disappear. C≡C/C≡N bands appear near 2100–2250.',src:'pe6-cp:1'},
  {s:'Practice Exam 6: Chem/Phys',disc:'organic_chem',aamc:'4D',q:'Which technique gives the RATIO of two isomeric products in a mixture?',choices:['IR (functional groups)','¹H NMR (peak integrals)','UV (conjugation)','Atomic absorption (metals)'],ans:1,exp:'**NMR integrals are proportional to the number of H atoms**, so comparing a unique peak from each isomer gives their mole ratio. IR shows which groups are present, not how much of each.',src:'pe6-cp:2'},
  {s:'Practice Exam 6: Chem/Phys',disc:'organic_chem',aamc:'5B',q:'A carbon carries H, OH, a benzyl group and a phenyl group. Is the molecule chiral?',choices:['Yes, that carbon is a stereocenter','No, two of its groups are the same','No, an OH can\'t be on a stereocenter','Only if the rings are substituted'],ans:0,exp:'**Four different groups on one sp³ carbon = stereocenter → chiral** (if there\'s no mirror plane). Benzyl (CH₂C₆H₅) ≠ phenyl (C₆H₅).',src:'pe6-cp:4'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4A',q:'How do you get velocity from a displacement-versus-time graph?',choices:['From the slope','From the average y-value','From the area under the curve','From the spread of the data'],ans:0,exp:'**Slope of x–t = velocity; slope of v–t = acceleration; area under v–t = displacement.**',src:'pe6-cp:5'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4C',q:'DNA moves through an electric field in gel electrophoresis. Which property makes it move?',choices:['It has a net electric charge','It is a long chain','It is very long (170 kb)','It contains deoxyribose'],ans:0,exp:'Only **charged** objects feel a force in an E field (F = qE). DNA\'s phosphate backbone is **negative**, so it moves toward the + electrode.',src:'pe6-cp:6'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'How would you describe a buffer at pH 8.2?',choices:['Weakly acidic','Weakly basic','Strongly acidic','Strongly basic'],ans:1,exp:'pH > 7 is basic, and **8.2 is close to 7**, so it\'s weakly basic. Strongly basic solutions are around pH 12–14.',src:'pe6-cp:7'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'Boric acid has pKa 9.2. At pH 8.2, what is the ratio [base]/[acid]?',choices:['10','2','0.2','0.1'],ans:3,exp:'**Henderson–Hasselbalch:** ratio = 10^(pH − pKa) = 10^(−1) = 0.1. pH below pKa → the acid form dominates (ratio < 1).',src:'pe6-cp:8'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'A reaction is spontaneous at 20 °C. What MUST be true at that temperature?',choices:['ΔG < 0 and ΔS < 0','ΔG < 0 and ΔH < 0','Only ΔH < 0','Only ΔG < 0'],ans:3,exp:'**Spontaneous means ΔG < 0, nothing more.** ΔH and ΔS can have either sign as long as ΔH − TΔS ends up negative.',src:'pe6-cp:9'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Which residue can NOT be phosphorylated?',choices:['Phenylalanine','Serine','Threonine','Tyrosine'],ans:0,exp:'Kinases attach phosphate to an **–OH**. Ser, Thr and Tyr have one; **Phe is Tyr without the OH**.',src:'pe6-cp:10'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4A',q:'When oxygen use rises 4×, energy use also rises about 4×. What is the relationship?',choices:['E ∝ V','E ∝ V²','E ∝ 1/V','E ∝ 1/V²'],ans:0,exp:'**Same factor up = directly proportional (linear).** If E ∝ V², a 4× rise in V would give 16× in E.',src:'pe6-cp:11'},
  {s:'Practice Exam 6: Chem/Phys',disc:'organic_chem',aamc:'5B',q:'On a cyclohexane ring with a tert-butyl group, the methyl ends up axial in the favored chair. Why?',choices:['The bulky tert-butyl takes the equatorial spot','Methyl groups always prefer axial','Axial positions have fewer 1,3-interactions','The ring stays flat'],ans:0,exp:'The **biggest group (tert-butyl) locks itself equatorial** to avoid 1,3-diaxial strain. Depending on the cis/trans relationship, that can force the methyl axial.',src:'pe6-cp:12'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'A Schiff base (imine) links a carbon to nitrogen with C=N. How is that carbon hybridized?',choices:['sp','sp²','sp³','sp³d'],ans:1,exp:'Carbon with **one double bond and three groups → trigonal planar → sp²**. (Retinal binds opsin\'s lysine this way.)',src:'pe6-cp:13'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'Adding a compound raises an enzyme\'s KM AND lowers its Vmax. What kind of inhibitor is it?',choices:['A mixed inhibitor','An uncompetitive inhibitor','A competitive inhibitor','A noncompetitive inhibitor'],ans:0,exp:'Competitive: KM↑, Vmax same. Pure noncompetitive: KM same, Vmax↓. Uncompetitive: both ↓. **KM↑ with Vmax↓ = mixed.**',src:'pe6-cp:15'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'AMP activates glycogen phosphorylase, and phosphate (Pi) is its substrate. Which conditions make product fastest?',choices:['High AMP and high Pi','High AMP and low Pi','Low AMP and high Pi','Low AMP and low Pi'],ans:0,exp:'**More activator + more substrate = faster rate** (until the enzyme is saturated).',src:'pe6-cp:16'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4C',q:'Photoelectrons freed in a metal detector travel through a wire circuit. What kind of conduction carries them?',choices:['Electrolytic conduction','Ionic conduction','Metallic conduction','Photonic conduction'],ans:2,exp:'In wires, **free electrons** carry current: **metallic** conduction. Ionic/electrolytic conduction uses moving ions in solution.',src:'pe6-cp:17'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'5E',q:'Aluminum\'s heat of fusion is 4.0 × 10⁵ J/kg. How much heat melts 50 g already at its melting point?',choices:['1 × 10⁴ J','2 × 10⁴ J','1 × 10⁵ J','4 × 10⁵ J'],ans:1,exp:'**q = mL** = 0.050 kg × 4.0 × 10⁵ J/kg = 2 × 10⁴ J. There\'s no ΔT during a phase change.',src:'pe6-cp:18'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'A glucose molecule has the radioactive isotope ¹⁸F in place of one OH (C₆H₁₁FO₅). What is its molar mass?',choices:['179 g/mol','180 g/mol','181 g/mol','182 g/mol'],ans:2,exp:'6(12) + 11(1) + **18** + 5(16) = 72 + 11 + 18 + 80 = **181 g/mol**. Use the isotope\'s mass number (18), not the periodic-table 19.',src:'pe6-cp:19'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4E',q:'Compared with stable ¹⁹F, an atom of ¹⁸F has one fewer:',choices:['neutron','electron','proton','positron'],ans:0,exp:'Same element = **same proton count (9)**. The mass number dropped by 1, so it has **one fewer neutron** (9 instead of 10).',src:'pe6-cp:20'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'A biotin nitrogen donates its lone pair to CO₂, then later pulls an H⁺ off a threonine. What are its two roles?',choices:['Electrophile, then general acid','Nucleophile, then general base','Electrophile, then general base','Nucleophile, then general acid'],ans:1,exp:'**Giving electrons to a carbon = nucleophile. Taking a proton = base.** Electrophiles and acids do the opposite.',src:'pe6-cp:22'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'Pyruvate\'s carboxylate and ketone oxygens are held by Arg and Gln side chains. How does pyruvate interact?',choices:['As a hydrogen-bond donor','As a hydrogen-bond acceptor','Through hydrophobic contacts','Through London forces only'],ans:1,exp:'Its **C=O and COO⁻ oxygens have lone pairs** but no O–H, so pyruvate can only **accept** H-bonds from the N–H groups.',src:'pe6-cp:23'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5E',q:'A Thr residue first loses its H⁺, then takes an H⁺ from the substrate. What is its role?',choices:['Proton shuttle','Holding a cofactor in place','Binding CO₂ covalently','Transferring a methyl group'],ans:0,exp:'Passing a proton along (give one, take one) = **proton shuttle**, a type of acid–base catalysis.',src:'pe6-cp:24'},
  {s:'Practice Exam 6: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'Partial hydrolysis of a tripeptide gives Gly, Ala, Ala–Gly and Gly–Ala. Which tripeptide was it?',choices:['Gly–Gly–Ala','Gly–Ala–Ala','Ala–Gly–Gly','Ala–Gly–Ala'],ans:3,exp:'You need **both** Ala–Gly **and** Gly–Ala, so Gly must be in the middle with Ala on each side: **Ala–Gly–Ala**. Check each choice\'s two dipeptides.',src:'pe6-cp:25'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'What volume of O₂ at STP burns 1 mol of CH₄ completely?',choices:['22.4 L','33.6 L','44.8 L','67.2 L'],ans:2,exp:'**CH₄ + 2O₂ → CO₂ + 2H₂O.** 2 mol O₂ × 22.4 L = 44.8 L. Balance the equation first.',src:'pe6-cp:26'},
  {s:'Practice Exam 6: Chem/Phys',disc:'organic_chem',aamc:'4D',q:'Which alcohol\'s ¹H NMR spectrum shows a doublet?',choices:['Ethanol','2-Propanol','2-Methyl-2-propanol','1-Butanol'],ans:1,exp:'**n + 1 rule:** a doublet means 1 neighboring H. In (CH₃)₂CH–OH, the six CH₃ hydrogens neighbor the single CH → doublet. Ethanol\'s CH₃ is a triplet; tert-butanol\'s is a singlet.',src:'pe6-cp:27'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4B',q:'A rod floats half-submerged in water. In which fluid would it float completely submerged (just barely)?',choices:['Density 0.5 g/cm³','Density 1.0 g/cm³','Density 2.0 g/cm³','Density 10 g/cm³'],ans:0,exp:'**Fraction submerged = ρ_object / ρ_fluid.** Half in water → ρ_rod = 0.5 g/cm³. It is fully submerged when ρ_fluid = ρ_rod.',src:'pe6-cp:28'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'A protein is studied at a pH equal to its isoelectric point. What is its net charge?',choices:['+1','0','−1','−2'],ans:1,exp:'**pI = the pH where the net charge is zero.** Below the pI the protein is positive; above it, negative.',src:'pe6-cp:29'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Oxidative damage links protein chains through a covalent bond between two phenol side chains. Which residue is involved?',choices:['Cysteine','Tryptophan','Tyrosine','Phenylalanine'],ans:2,exp:'**Tyrosine is the phenol amino acid.** Tyr–Tyr dimers are a classic oxidative crosslink. Cys makes disulfides instead.',src:'pe6-cp:30'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4E',q:'An isotope emits gamma rays. What particles is it giving off?',choices:['Electrons','Helium nuclei','Neutrons','Photons'],ans:3,exp:'**γ = high-energy photons.** α = helium nuclei; β⁻ = electrons.',src:'pe6-cp:32'},
  {s:'Practice Exam 6: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'A labeling reagent reacts with amines and thiols (–SH). Which two residues can it label?',choices:['Asp and Glu','Ser and Thr','Lys and Cys','Asn and Gln'],ans:2,exp:'**Lys = side-chain amine (–NH₂); Cys = thiol (–SH).** Asp/Glu are acids, Ser/Thr are alcohols, and Asn/Gln are amides (weak nucleophiles).',src:'pe6-cp:34'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'Physiological saline is 0.15 M NaCl (58.5 g/mol). What mass of NaCl is in 1.0 L?',choices:['0.2 g','1.5 g','4.1 g','8.8 g'],ans:3,exp:'**mass = M × V × molar mass** = 0.15 × 1.0 × 58.5 ≈ 8.8 g (about 0.9% saline).',src:'pe6-cp:35'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'4.0 mL of a 20 mg/mL solution of an 80 kDa protein is used. How many moles of protein is that?',choices:['2 mmol','300 μmol','1 μmol','40 nmol'],ans:2,exp:'Mass = 4.0 mL × 20 mg/mL = 80 mg. **80 kDa = 80,000 g/mol**, so 0.080 g ÷ 80,000 = 1 × 10⁻⁶ mol = **1 μmol**.',src:'pe6-cp:36'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'A protein is labeled in water and keeps its full function. Where did the label most likely attach?',choices:['Near the active site','At the C-terminus','On a residue on the surface','On a buried hydrophobic residue'],ans:2,exp:'A water-soluble reagent reaches **surface residues** first. Labeling the active site would destroy its function, and buried residues are out of reach.',src:'pe6-cp:37'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'How many moles of CoCl₂ are in 5.0 mL of a 1.0 mM solution?',choices:['5 μmol','50 μmol','100 μmol','1 mmol'],ans:0,exp:'**n = M × V** = 1.0 × 10⁻³ mol/L × 5.0 × 10⁻³ L = 5 × 10⁻⁶ mol = 5 μmol. Convert mM and mL first.',src:'pe6-cp:38'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'4C',q:'A battery has E°cell = 4.0 V, and its cathode has E°red = +1.0 V. What is the anode\'s reduction potential?',choices:['+4.0 V','+0.3 V','−1.0 V','−3.0 V'],ans:3,exp:'**E°cell = E°cathode − E°anode** → 4.0 = 1.0 − E°anode → E°anode = −3.0 V. Both values in the formula are reduction potentials.',src:'pe6-cp:41'},
  {s:'Practice Exam 6: Chem/Phys',disc:'organic_chem',aamc:'5D',q:'A protein binds Co²⁺ tightly through glutamate side chains. Which group does the binding?',choices:['An amide','A carboxylate','An imidazole','A hydroxyl'],ans:1,exp:'Glutamate\'s side chain is **–COO⁻**: its negative oxygens attract a metal cation. (His\'s imidazole also binds metals, but that\'s histidine.)',src:'pe6-cp:42'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'4C',q:'What does a dissolved LiPF₆ salt do inside a lithium battery?',choices:['It acts as the anode','It acts as an oxidizing agent','It serves as the electrolyte','It acts as the cathode'],ans:2,exp:'A dissolved salt splits into **ions (Li⁺, PF₆⁻) that carry charge between the electrodes**: the electrolyte. The electrodes are the solids where redox happens.',src:'pe6-cp:43'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Which lipid is NOT a membrane lipid?',choices:['Glycerophospholipids','Sphingolipids','Sterols','Triacylglycerols'],ans:3,exp:'**Triacylglycerols are storage fat**, with no polar head group to face water. Phospholipids, sphingolipids and cholesterol make up membranes.',src:'pe6-cp:44'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'How many carbon atoms does deoxyadenylate (dAMP) contain?',choices:['3','5','8','10'],ans:3,exp:'**Adenine has 5 carbons and deoxyribose has 5.** Phosphate adds none. Total = 10.',src:'pe6-cp:45'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biology',aamc:'4B',q:'Why is the left ventricle\'s wall thicker than the right\'s?',choices:['It pumps blood to the lungs','It fills first from the vena cava','It must push blood through the whole body','It holds more deoxygenated blood'],ans:2,exp:'**Left = systemic circuit** (high resistance, high pressure); right = the short, low-pressure lung circuit. More work → more muscle. The vena cava empties into the **right** atrium.',src:'pe6-cp:46'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4E',q:'Helium has two electrons in its 1s orbital. What is their total spin?',choices:['0','½','1','2'],ans:0,exp:'**Pauli exclusion:** two electrons in the same orbital must have **opposite spins** (+½ and −½), which sum to 0.',src:'pe6-cp:47'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'Three Trp residues bind cellulose by donating H-bonds from their ring N–H. Which substitution keeps that ability best?',choices:['Trp → Tyr','Trp → Phe','Trp → Leu','Trp → Ala'],ans:0,exp:'**Tyr keeps an aromatic ring AND has an –OH H-bond donor.** Phe has the ring with no donor; Leu and Ala lose both.',src:'pe6-cp:48'},
  {s:'Practice Exam 6: Chem/Phys',disc:'biochemistry',aamc:'5D',q:'What do the many Ser and Thr residues on a protein\'s surface most likely do?',choices:['Catalyze reactions','Make the protein clump','Add charge to the surface','Hold a layer of water around it'],ans:3,exp:'Ser and Thr are **uncharged but polar**: their –OH groups **hydrogen bond with water**, keeping the protein dissolved.',src:'pe6-cp:49'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5A',q:'What is the name of NH₄Cl?',choices:['Ammonium chloride','Ammonia hydrochloride','Chlorine amide','Nitrogen tetrahydrogen chloride'],ans:0,exp:'**NH₄⁺ = ammonium**, Cl⁻ = chloride. Name ionic compounds cation first, then anion. Greek prefixes are only for molecular compounds.',src:'pe6-cp:50'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4D',q:'What is the energy of a 750 MHz radio photon? (h = 6.6 × 10⁻³⁴ J·s)',choices:['3.0 × 10⁻²⁵ J','5.0 × 10⁻²⁵ J','7.0 × 10⁻²⁵ J','9.0 × 10⁻²⁵ J'],ans:1,exp:'**E = hf** = 6.6 × 10⁻³⁴ × 7.5 × 10⁸ ≈ 5.0 × 10⁻²⁵ J. Radio photons carry far less energy than visible light (about 10⁻¹⁹ J).',src:'pe6-cp:51'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4C',q:'Using γ = 2πf/B with f = 750 MHz and B = 18 T, what is γ?',choices:['87 × 2π MHz/T','63 × 2π MHz/T','42 × 2π MHz/T','26 × 2π MHz/T'],ans:2,exp:'750 ÷ 18 ≈ 41.7, so **γ ≈ 42 × 2π MHz/T** (the proton\'s known value). Plug the given numbers into the given equation.',src:'pe6-cp:52'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'4B',q:'The same reaction run colder produces a smaller VOLUME of gas. What best explains this?',choices:['The reaction doesn\'t occur when cold','Gas takes up less volume at lower T','Fewer moles of product form','There isn\'t enough heat to melt the solid'],ans:1,exp:'**Charles\'s law: V ∝ T** (at fixed P and n). The same moles of gas take up less space when colder.',src:'pe6-cp:53'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'On a phase diagram, a path crosses directly from the solid region to the vapor region. What is it?',choices:['Sublimation','Melting','Fusion','Vaporization'],ans:0,exp:'**Solid → gas with no liquid = sublimation.** Melting and fusion are the same thing (solid → liquid).',src:'pe6-cp:54'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5E',q:'NH₄NO₃ decomposes with a negative ΔH, yet it is stable at room temperature. How do you describe its energetics?',choices:['Endothermic, no activation energy','Endothermic, high activation energy','Exothermic, no activation energy','Exothermic, high activation energy'],ans:3,exp:'**Negative ΔH = exothermic.** Being stable until triggered means a **high Ea** barrier: thermodynamics (ΔH) and kinetics (Ea) are separate.',src:'pe6-cp:55'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'4E',q:'A reaction forms 1 mol N₂, ½ mol O₂ and 2 mol H₂O, all as gases. What fraction of the gas is water vapor?',choices:['1/7','2/7','3/7','4/7'],ans:3,exp:'Total gas = 1 + 0.5 + 2 = 3.5 mol. **Mole fraction** of H₂O = 2 ÷ 3.5 = 4/7.',src:'pe6-cp:56'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4E',q:'An isotope with a 2-year half-life had an activity of 8 Ci six years ago. What is its activity now?',choices:['0.8 Ci','1.0 Ci','1.3 Ci','2.7 Ci'],ans:1,exp:'6 years = 3 half-lives: 8 → 4 → 2 → **1 Ci**. Activity halves on the same schedule as the amount.',src:'pe6-cp:57'},
  {s:'Practice Exam 6: Chem/Phys',disc:'physics',aamc:'4E',q:'²⁴¹Am (Z = 95) emits an alpha particle. What nucleus is left?',choices:['²³⁷Bk','²³⁷Np','²³⁹Cm','²³⁹Pu'],ans:1,exp:'**α = ⁴He: mass −4, Z −2.** 241 − 4 = 237; Z 95 − 2 = 93 = neptunium.',src:'pe6-cp:58'},
  {s:'Practice Exam 6: Chem/Phys',disc:'gen_chem',aamc:'5B',q:'In the best Lewis structure of carbon monoxide, how many bonds join C and O?',choices:['1','2','3','4'],ans:2,exp:'CO has 10 valence electrons. A **triple bond** plus one lone pair on each atom gives both atoms an octet. (N₂ is the same.)',src:'pe6-cp:59'},
];
